"""Topic-specific introductions for eighteen UI frameworks and libraries."""
import runpy
from pathlib import Path
api = runpy.run_path(str(Path(__file__).with_name('author-web.py')))
L, build = api['lesson'], api['build']

build('vue',
 'Vue builds a page from small parts called components. It connects values to the page and updates the page when those values change. Start with a greeting, then add choices, lists and a little memory.',
 'Use a Vue 3 project made with the official create-vue tool. Put single-file examples in App.vue unless file names say otherwise. These need the Vue build tool and do not run in the plain playground.',
 'Uses Vue 3 Single-File Components and the Composition API with script setup.', [
 L('Show a value in a template', 'A Vue template describes the page. Double curly brackets show a JavaScript value as text.', 'vue', '<script setup>\nconst club = "Garden club";\n</script>\n<template><h1>{{ club }}</h1></template>', 'The page shows Garden club as its heading.', 'Use curly brackets for text values. Do not put raw user strings into v-html.', 'Change the club value and check the heading.', 'What does {{ club }} show?', 'The value named club', 'The literal word template', slug='introduction'),
 L('Remember a changing value', 'A ref is a small container for a value that Vue can watch. Templates unwrap its value for you.', 'vue', '<script setup>\nimport { ref } from "vue";\nconst count = ref(0);\n</script>\n<template><button @click="count++">Books: {{ count }}</button></template>', 'Each click increases the displayed count by one.', 'In script code, use count.value to read or change the ref value. Templates can use count directly.', 'Start the counter at 5 instead of 0.', 'What does ref add to this value?', 'Vue can track its changes', 'It saves the value to every device'),
 L('Bind an attribute', 'v-bind connects an HTML attribute to a JavaScript value. A colon is the short form of v-bind.', 'vue', '<script setup>\nconst destination = "#books";\n</script>\n<template><a :href="destination">Book list</a><h2 id="books">Books</h2></template>', 'The link points to the books heading using the bound value.', 'href="destination" would use that word as the address. :href evaluates the JavaScript name.', 'Change the destination and matching heading id.', 'What does the colon in :href mean?', 'Use the value of a JavaScript expression', 'Always open a new tab'),
 L('Choose whether to show a part', 'v-if includes a page part when its rule is true. v-else gives another part for the false case.', 'vue', '<script setup>\nimport { ref } from "vue";\nconst ready = ref(false);\n</script>\n<template><button @click="ready = !ready">Change</button><p v-if="ready">Ready to read</p><p v-else>Choose a book</p></template>', 'The button switches between the two messages.', 'Place v-else immediately after its matching v-if element.', 'Change the two messages to match a club task.', 'Which message appears when ready is false?', 'Choose a book', 'Ready to read'),
 L('Show a keyed list', 'v-for makes one page part per list item. A stable key helps Vue follow the right item when the list changes.', 'vue', '<script setup>\nconst books = [{id:1,title:"Moon Trip"},{id:2,title:"Garden Days"}];\n</script>\n<template><ul><li v-for="book in books" :key="book.id">{{ book.title }}</li></ul></template>', 'The page shows both book titles as list items.', 'Use a stable item id for the key. A position can point to a different item after sorting.', 'Add a third book with a new id.', 'Why use book.id as the key?', 'It stays with the same book when items move', 'It changes the font size'),
 L('Connect an input with v-model', 'v-model connects a form field to a value. Typing updates the value, and changing the value updates the field.', 'vue', '<script setup>\nimport { ref } from "vue";\nconst name = ref("");\n</script>\n<template><label>Name <input v-model="name"></label><p>Hello, {{ name }}</p></template>', 'The greeting follows the name typed into the field.', 'Keep a visible label. v-model does not explain the field to someone using a screen reader.', 'Type a name and then clear the field.', 'What updates name in this example?', 'Typing into the linked input', 'Only refreshing the browser'),
 L('Calculate a value from state', 'A computed value is based on other reactive values. Vue can update it when the values it reads change.', 'vue', '<script setup>\nimport { ref, computed } from "vue";\nconst books = ref(3);\nconst pages = computed(() => books.value * 10);\n</script>\n<template><button @click="books++">Add book</button><p>{{ pages }} pages planned</p></template>', 'The page starts at 30 pages. Adding a book changes it to 40.', 'A computed getter should calculate a result, not change unrelated state.', 'Change the pages-per-book number from 10 to 12.', 'When does this computed result need to change?', 'When books changes', 'Only when the CSS changes'),
 L('Pass a prop to a child', 'Props are values a parent gives a child component. The child reads them to decide what to show.', 'vue', '<!-- BookCard.vue -->\n<script setup>defineProps({ title: String });</script>\n<template><h2>{{ title }}</h2></template>\n\n<!-- App.vue, separate file -->\n<script setup>import BookCard from "./BookCard.vue";</script>\n<template><BookCard title="Moon Trip" /></template>', 'The child card displays the title given by its parent.', 'Save the two parts as separate files. Treat props as inputs; do not change them directly in the child.', 'Pass a different title into BookCard.', 'Who supplies a child prop?', 'The parent component', 'The CSS compiler'),
 L('Send a child event', 'A child can emit an event to ask its parent to do something. This keeps the child from owning the parent\'s state.', 'vue', '<!-- ChooseButton.vue -->\n<script setup>const emit = defineEmits(["choose"]);</script>\n<template><button @click="emit(\'choose\', \'Moon Trip\')">Choose</button></template>\n\n<!-- App.vue, separate file -->\n<script setup>import ChooseButton from "./ChooseButton.vue"; import { ref } from "vue"; const choice=ref("");</script>\n<template><ChooseButton @choose="choice = $event" /><p>{{ choice }}</p></template>', 'Clicking the child button makes the parent show Moon Trip.', 'A component event is not the same as an ordinary DOM event that bubbles through every ancestor.', 'Change the value sent with the choose event.', 'What carries the chosen title to the parent?', 'The emitted choose event value', 'The component file name'),
 L('Leave a slot for content', 'A slot leaves a place where a parent can supply page content. It makes a wrapper reusable.', 'vue', '<!-- NoteBox.vue -->\n<template><aside><h2>Note</h2><slot>No message yet</slot></aside></template>\n\n<!-- App.vue, separate file -->\n<script setup>import NoteBox from "./NoteBox.vue";</script>\n<template><NoteBox><p>Bring a notebook.</p></NoteBox></template>', 'The supplied paragraph appears inside the note box after its heading.', 'Slot content belongs to the parent that supplies it. Use props when you need a named data value instead.', 'Remove the supplied paragraph to see the fallback.', 'When is No message yet used?', 'When no slot content is supplied', 'Whenever the parent has a script'),
 L('Clean up a timer', 'A mounted hook can start work after a component joins the page. An unmounted hook can stop that work when the component leaves.', 'vue', '<script setup>\nimport { ref, onMounted, onUnmounted } from "vue";\nconst seconds=ref(0); let timer;\nonMounted(()=>{timer=setInterval(()=>seconds.value++,1000);});\nonUnmounted(()=>clearInterval(timer));\n</script>\n<template><p>{{ seconds }} seconds</p></template>', 'The number increases once per second while the component is mounted.', 'Stop repeating jobs when they are no longer needed. Otherwise old timers can keep running.', 'Explain which hook stops the timer.', 'Why call clearInterval on unmount?', 'To stop work belonging to the removed component', 'To erase every browser setting'),
 L('Build a small reading list', 'A form and a reactive array can work together. Each submitted title becomes a new item with its own stable id.', 'vue', '<script setup>\nimport { ref } from "vue";\nconst title=ref(""); const books=ref([]); let nextId=1;\nfunction add(){if(title.value.trim()){books.value.push({id:nextId++,title:title.value.trim()});title.value="";}}\n</script>\n<template><form @submit.prevent="add"><label>Book <input v-model="title"></label><button>Add</button></form><ul><li v-for="book in books" :key="book.id">{{ book.title }}</li></ul></template>', 'Submitting a non-empty title adds it to the list and clears the field. Reloading resets this in-memory list.', 'This sample does not save to disk or a server. State alone does not provide long-term storage.', 'Add two books and explain why their ids differ.', 'What does @submit.prevent stop?', 'The form\'s normal page submission', 'Vue from updating the list'),
])

def three(body, material='new THREE.MeshBasicMaterial({color:0x174a8b})', render=True):
    return 'import * as THREE from "three";\nconst scene=new THREE.Scene();\nconst camera=new THREE.PerspectiveCamera(60,320/200,0.1,100);camera.position.z=4;\nconst renderer=new THREE.WebGLRenderer({antialias:true});renderer.setSize(320,200);\ndocument.body.append(renderer.domElement);\nconst geometry=new THREE.BoxGeometry(1,1,1);\nconst material='+material+';\nconst cube=new THREE.Mesh(geometry,material);scene.add(cube);\n'+body+('\nrenderer.render(scene,camera);' if render else '')

build('threejs',
 'Three.js helps JavaScript draw 3D scenes in a browser. A scene holds objects, a camera chooses the view and a renderer draws the picture. Learn one cube before adding movement, light and cleanup.',
 'Use a browser project with the three package installed and a module build tool. Each example creates its own canvas. Run one at a time. These library imports are not supported by this site\'s plain runner.',
 'Uses stable Three.js scene, camera, geometry, material and WebGLRenderer APIs.', [
 L('Draw your first cube', 'A mesh joins a shape with a material. The scene holds the mesh, and the renderer draws it from the camera\'s view.', 'javascript', three('cube.rotation.y=0.4;'), 'A blue cube appears on the new canvas, turned slightly so its shape is visible.', 'Adding an object to a scene does not draw it by itself. Call render with a scene and camera.', 'Change the cube colour in MeshBasicMaterial.', 'What two things make a Mesh?', 'Geometry and material', 'A password and a URL', slug='introduction'),
 L('Move the camera', 'The camera is the viewpoint into a scene. Moving it changes what you see without moving the object itself.', 'javascript', three('camera.position.set(2,2,4);camera.lookAt(0,0,0);'), 'The camera looks down at the cube from the side and above.', 'After moving the camera, aim it where you intend to look. A misplaced camera can look away from the scene.', 'Change the camera x position and compare the view.', 'What does camera.lookAt choose?', 'The point the camera faces', 'The colour of the cube'),
 L('Choose a different geometry', 'Geometry describes an object\'s shape. A sphere geometry uses small triangles to approximate a round surface.', 'javascript', three('scene.remove(cube);\nconst ball=new THREE.Mesh(new THREE.SphereGeometry(0.7,24,16),material);scene.add(ball);'), 'A blue ball is drawn instead of the cube.', 'More segments make a smoother shape but require more work. Use enough detail for the displayed size.', 'Change the sphere radius from 0.7 to 1.', 'What does geometry describe?', 'The object\'s shape', 'The page\'s route address'),
 L('Show the shape as lines', 'A material tells the renderer how a shape should look. The wireframe option shows the geometry\'s triangle edges.', 'javascript', three('cube.rotation.set(0.3,0.5,0);','new THREE.MeshBasicMaterial({color:0x174a8b,wireframe:true})'), 'The cube appears as blue lines rather than filled faces.', 'Wireframe is a material display choice. It does not change the underlying geometry.', 'Switch wireframe to false and compare the result.', 'What changes when wireframe is true?', 'How the surface is displayed', 'The number of cameras'),
 L('Place an object', 'An object\'s position moves it along three scene axes: x, y and z. The default position is the origin, where all three are zero.', 'javascript', three('cube.position.set(1,0.5,0);'), 'The cube moves right and upward relative to this camera view.', 'Scene units are not CSS pixels. Their apparent size depends on the camera and distance.', 'Move the cube to x=-1.', 'How many axes are in this position?', 'Three: x, y and z', 'Only left and top'),
 L('Turn an object', 'Rotation turns an object around an axis. Three.js uses radians for these angles.', 'javascript', three('cube.rotation.y=Math.PI/4;cube.rotation.x=Math.PI/8;'), 'The cube is turned 45 degrees around y and 22.5 degrees around x.', 'Do not pass 45 when you mean 45 degrees. Convert degrees to radians or use a helper.', 'Set the y angle to Math.PI/2.', 'What unit does this rotation use?', 'Radians', 'Pixels'),
 L('Resize an object with scale', 'Scale multiplies an object\'s size on each axis. A scale of one keeps its original size.', 'javascript', three('cube.scale.set(2,0.5,1);'), 'The cube becomes twice as wide and half as tall, while its depth stays unchanged.', 'Non-uniform scale can stretch a shape. Use equal values when you want to keep its proportions.', 'Set all three scale values to 1.5.', 'What does a y scale of 0.5 do?', 'Halves the height', 'Adds half a pixel of margin'),
 L('Move a group together', 'A Group can hold several objects. Moving the group moves all its children together.', 'javascript', three('scene.remove(cube);\nconst group=new THREE.Group();group.add(cube);\nconst second=new THREE.Mesh(geometry,material);second.position.x=1.5;group.add(second);scene.add(group);group.position.x=-0.7;'), 'Two cubes appear together, positioned as one group.', 'A child position is relative to its parent group. Keep local and world positions distinct.', 'Move the group upward and watch both cubes.', 'What happens when this group moves?', 'Both child cubes move with it', 'Only the camera changes'),
 L('Light a shaded material', 'Some materials respond to light. MeshStandardMaterial needs lighting so its surfaces can show shape and shading.', 'javascript', three('scene.add(new THREE.AmbientLight(0xffffff,1));\nconst light=new THREE.DirectionalLight(0xffffff,2);light.position.set(3,4,5);scene.add(light);cube.rotation.y=0.5;','new THREE.MeshStandardMaterial({color:0x174a8b,roughness:0.6})'), 'The cube faces have different brightness because of the light direction.', 'A lit material in a scene with no light may appear dark. MeshBasicMaterial does not need light.', 'Move the directional light to the other side.', 'Which material in this example responds to light?', 'MeshStandardMaterial', 'MeshBasicMaterial'),
 L('Animate using time', 'An animation loop draws new frames. Using elapsed time makes motion less dependent on how many frames the device can draw.', 'javascript', three('renderer.setAnimationLoop(time=>{cube.rotation.y=time*0.001;renderer.render(scene,camera);});',render=False), 'The cube turns continuously around its y axis.', 'Do not add a fixed angle per frame if you need a consistent speed. Also respect reduced-motion preferences in a real interface.', 'Reduce the time multiplier to slow the turn.', 'Why base rotation on time?', 'To make speed less dependent on frame rate', 'To make the cube a static image'),
 L('Resize the camera view', 'A perspective camera needs the canvas aspect ratio. When the drawing size changes, update that ratio and its projection matrix.', 'javascript', three('const width=480,height=240;\nrenderer.setSize(width,height);camera.aspect=width/height;camera.updateProjectionMatrix();'), 'The canvas becomes wider while the camera uses the matching shape.', 'Changing only the canvas size can stretch the view. Keep the camera aspect ratio in step.', 'Try a square width and height.', 'Why call updateProjectionMatrix?', 'To apply the changed camera projection settings', 'To add another cube'),
 L('Clean up a scene', 'GPU resources need explicit cleanup when a scene is no longer used. Stop its animation and dispose of geometry, materials and renderer resources.', 'javascript', three('renderer.render(scene,camera);\n// Call this when this scene is removed:\nfunction disposeScene(){renderer.setAnimationLoop(null);geometry.dispose();material.dispose();renderer.dispose();renderer.domElement.remove();}\n// disposeScene();',render=False), 'Calling disposeScene removes this example\'s canvas and releases its owned resources.', 'Only dispose resources when no remaining object uses them. Shared materials may belong to more than one mesh.', 'List the resources this cleanup owns.', 'Why stop the animation loop during cleanup?', 'To stop rendering a scene that is no longer used', 'To save the cube to a database'),
])

def d3(body):
    return 'import * as d3 from "d3";\nconst svg=d3.select("body").append("svg").attr("width",320).attr("height",200).attr("viewBox","0 0 320 200");\n'+body

build('d3',
 'D3 connects data to page elements. It can choose positions, colours and labels to make a chart. Learn a few SVG shapes, then connect a small list of numbers to a bar chart you can explain.',
 'Use a browser project with D3 7 installed. These module examples append an SVG to the page. Run one example at a time with a bundler; the plain playground does not include D3.',
 'Uses D3 7 selections, joins, scales, axes and SVG shape generators.', [
 L('Select and append an SVG shape', 'A D3 selection points to page elements. append creates a child element, and attr sets one of its attributes.', 'javascript', d3('svg.append("circle").attr("cx",80).attr("cy",80).attr("r",30).attr("fill","navy");'), 'A navy circle appears at x=80, y=80 with radius 30.', 'SVG uses its own shape attributes such as cx and r. They are not ordinary CSS margin values.', 'Change the circle radius to 40.', 'What does append("circle") create?', 'An SVG circle element', 'A database row', slug='introduction'),
 L('Put data into a join', 'A data join matches data values to elements. join creates missing elements and can later update or remove them.', 'javascript', d3('svg.selectAll("circle").data([10,20,30]).join("circle").attr("cx",(_d,i)=>50+i*90).attr("cy",80).attr("r",d=>d).attr("fill","teal");'), 'Three circles use radii 10, 20 and 30.', 'The data callback receives the current value and index. Do not confuse the value with its position.', 'Add a fourth number and adjust the available space.', 'What does d represent in the radius callback?', 'The current data value', 'The whole document'),
 L('Map numbers to positions', 'A linear scale maps one number range to another. The domain is the data range, and the range is the drawing range.', 'javascript', d3('const x=d3.scaleLinear().domain([0,100]).range([20,300]);\nsvg.append("circle").attr("cx",x(50)).attr("cy",80).attr("r",8);'), 'The value 50 maps to the middle of the drawing range, x=160.', 'A domain is about data; a range is about output positions. Reversing them gives the wrong mapping.', 'Calculate where x(100) will be.', 'What is the domain [0,100] describing?', 'The input data values', 'The SVG file names'),
 L('Give categories equal spaces', 'A band scale gives named categories separate spaces. bandwidth tells the width available for each category.', 'javascript', d3('const x=d3.scaleBand().domain(["Mon","Tue","Wed"]).range([20,300]).padding(0.2);\nsvg.selectAll("rect").data(["Mon","Tue","Wed"]).join("rect").attr("x",d=>x(d)).attr("y",50).attr("width",x.bandwidth()).attr("height",80).attr("fill","navy");'), 'Three equal-width bars occupy the weekday bands with gaps.', 'Use a category value that exists in the domain. An unknown category has no assigned band position.', 'Add Thu to the domain and data.', 'What does bandwidth return?', 'The width of one category band', 'The speed of the internet connection'),
 L('Draw bars from values', 'A bar chart uses height to show a number. SVG y positions grow downward, so a taller bar needs a smaller top y value.', 'javascript', d3('const values=[30,60,90];\nconst y=d3.scaleLinear().domain([0,100]).range([180,20]);\nsvg.selectAll("rect").data(values).join("rect").attr("x",(_d,i)=>30+i*90).attr("width",50).attr("y",d=>y(d)).attr("height",d=>180-y(d)).attr("fill","teal");'), 'The bars grow upward from y=180 for values 30, 60 and 90.', 'Do not use the scaled y coordinate as the bar height. Subtract it from the baseline.', 'Change the middle value and predict its height.', 'Why is height calculated as 180-y(d)?', 'To measure from the top of the bar to the baseline', 'To reverse the data order'),
 L('Add readable labels', 'Text labels tell readers what a chart value means. D3 can set text from the same data used for shapes.', 'javascript', d3('svg.selectAll("text").data([3,6,9]).join("text").attr("x",(_d,i)=>50+i*90).attr("y",100).attr("text-anchor","middle").text(d=>`${d} books`);'), 'The chart shows 3 books, 6 books and 9 books at separate positions.', 'Include units or clear context. A bare number can be hard to interpret.', 'Change books to plants in the labels.', 'What does text-anchor middle do?', 'Centres the text around its x position', 'Moves it to the bottom of the screen'),
 L('Draw an axis', 'An axis draws ticks and labels for a scale. Place its group at the edge of the chart where that scale should be read.', 'javascript', d3('const x=d3.scaleLinear().domain([0,10]).range([30,290]);\nsvg.append("g").attr("transform","translate(0,160)").call(d3.axisBottom(x).ticks(5));'), 'A horizontal number axis appears near the bottom of the SVG.', 'The axis uses the same scale as the data marks. A different domain would make labels disagree with the chart.', 'Change the domain to [0,20].', 'What should an axis share with its data marks?', 'The same scale', 'Only the same font file'),
 L('Connect points with a line', 'A line generator turns a list of points into an SVG path. Each point needs an x and y value.', 'javascript', d3('const points=[[20,150],[120,80],[220,110],[300,30]];\nconst line=d3.line().x(d=>d[0]).y(d=>d[1]);\nsvg.append("path").datum(points).attr("d",line).attr("fill","none").attr("stroke","navy").attr("stroke-width",3);'), 'A navy line connects the four points in their list order.', 'Use fill:none for this open line. A default fill can create an unwanted filled shape.', 'Move the second point upward by reducing its y value.', 'What decides the order of the connected points?', 'Their order in the data list', 'Their alphabetical names'),
 L('Make a small pie layout', 'A pie layout turns values into angles. An arc generator uses those angles to draw slice paths.', 'javascript', d3('const pie=d3.pie()([2,3,5]);const arc=d3.arc().innerRadius(0).outerRadius(70);\nsvg.append("g").attr("transform","translate(160,100)").selectAll("path").data(pie).join("path").attr("d",arc).attr("fill",(_d,i)=>["#174a8b","#18794e","#c76b00"][i]);'), 'The circle is divided into shares of 20%, 30% and 50%.', 'Use only a few categories and provide labels or a table. Colour alone does not tell a reader the values.', 'Explain which input creates half of the circle.', 'Which value makes the largest slice?', '5', '2'),
 L('Update an existing join', 'Calling a join again with new data updates the matching elements. Extra old elements are removed by the join.', 'javascript', d3('function draw(values){svg.selectAll("circle").data(values).join("circle").attr("cx",(_d,i)=>60+i*80).attr("cy",100).attr("r",d=>d).attr("fill","teal");}\ndraw([10,20,30]);\ndraw([15,25]);'), 'The final chart has two circles with radii 15 and 25. The third old circle is removed.', 'For objects that can reorder, supply a stable key to data. Index matching alone can follow the wrong item.', 'Call draw with four values.', 'What happens to the extra third circle?', 'The join removes it', 'It always remains forever'),
 L('React to a chart event', 'D3 can attach an event handler to a shape. The handler receives the event and the datum for that shape.', 'javascript', d3('svg.selectAll("circle").data([3,5]).join("circle").attr("cx",(_d,i)=>80+i*120).attr("cy",100).attr("r",25).attr("fill","navy").on("click",(_event,d)=>console.log(`${d} books`));'), 'Clicking a circle logs its own book count.', 'A mouse handler alone is not an accessible control. Add an equivalent keyboard-accessible control when the action matters.', 'Explain which data value is logged for the second circle.', 'What is the second handler argument?', 'The clicked shape\'s data value', 'The whole stylesheet'),
 L('Give the chart a text explanation', 'A visual chart should have a useful name and a text explanation. A nearby table can provide exact values to readers who cannot use the picture.', 'javascript', d3('svg.attr("role","img").attr("aria-labelledby","chart-title chart-desc");\nsvg.append("title").attr("id","chart-title").text("Books read this week");\nsvg.append("desc").attr("id","chart-desc").text("Monday: 3 books. Tuesday: 5 books.");\nsvg.append("text").attr("x",20).attr("y",50).text("Monday 3; Tuesday 5");'), 'The SVG has an accessible title and description as well as visible summary text.', 'Do not claim a title alone explains a complex chart. Include the important trends and exact data in usable text.', 'Write a short chart description that states the key comparison.', 'What should the text alternative communicate?', 'The important meaning and data of the chart', 'Only the name of the JavaScript library'),
])

def chart(config, after=''):
    return 'import Chart from "chart.js/auto";\nconst canvas=document.createElement("canvas");\nconst holder=document.createElement("div");holder.style.cssText="position:relative;width:320px;height:240px";holder.append(canvas);document.body.append(holder);\nconst chart=new Chart(canvas,'+config+');\n'+after

build('chartjs',
 'Chart.js draws charts on a canvas. You supply labels, values and a few options. Learn how to choose a clear chart, label its numbers and update it without hiding the data from readers.',
 'Use a browser project with Chart.js 4 installed. Each example creates its own canvas inside a sized holder. Package imports need your project build tool and do not run in this playground.',
 'Uses Chart.js 4 and the chart.js/auto registration entry point.', [
 L('Create a bar chart', 'A bar chart compares amounts between categories. Chart.js pairs labels with the values in a dataset.', 'javascript', chart('{type:"bar",data:{labels:["Mon","Tue"],datasets:[{label:"Books",data:[3,5]}]},options:{maintainAspectRatio:false,scales:{y:{beginAtZero:true}}}}'), 'Two bars compare 3 books on Monday with 5 on Tuesday.', 'Keep label and data order in step. A swapped value tells the wrong story.', 'Add Wednesday with 4 books.', 'What does each bar height represent?', 'The matching dataset value', 'The number of letters in the label', slug='introduction'),
 L('Name a dataset', 'A dataset label explains what a set of values measures. It can appear in the legend and tooltips.', 'javascript', chart('{type:"bar",data:{labels:["A","B"],datasets:[{label:"Plants watered",data:[4,7]}]},options:{maintainAspectRatio:false}}'), 'The legend names the values Plants watered.', 'Use a real unit or measure name. Dataset 1 does not help a reader understand the numbers.', 'Choose a clear label for minutes spent reading.', 'What does the dataset label explain?', 'What the numbers measure', 'The canvas file path'),
 L('Use a line for ordered change', 'A line chart can show how a value changes across an ordered sequence, such as days.', 'javascript', chart('{type:"line",data:{labels:["Mon","Tue","Wed"],datasets:[{label:"Minutes read",data:[10,20,15],tension:0}]},options:{maintainAspectRatio:false}}'), 'Straight line segments connect the reading minutes in day order.', 'Do not join unrelated unordered categories with a line if that implies a change that does not exist.', 'Add Thursday with 25 minutes.', 'What makes days suitable for this line chart?', 'They have a meaningful order', 'They all have short names'),
 L('Show parts of one total', 'A doughnut chart shows shares of a total. It works best with a small number of clearly labelled categories.', 'javascript', chart('{type:"doughnut",data:{labels:["Stories","Science","Poems"],datasets:[{data:[5,3,2],backgroundColor:["#174a8b","#18794e","#c76b00"]}]},options:{maintainAspectRatio:false}}'), 'Stories make half of the total of ten books.', 'Do not use negative values for these part-to-whole slices. Provide a text list of the exact values too.', 'Calculate the science share of the total.', 'Which category is half of the total?', 'Stories', 'Poems'),
 L('Plot pairs with a scatter chart', 'A scatter chart places each item using an x value and a y value. It can show how two measurements relate.', 'javascript', chart('{type:"scatter",data:{datasets:[{label:"Pages and minutes",data:[{x:5,y:10},{x:10,y:18},{x:15,y:28}]}]},options:{maintainAspectRatio:false,scales:{x:{title:{display:true,text:"Pages"}},y:{title:{display:true,text:"Minutes"}}}}}'), 'Three points show page counts against reading minutes.', 'Label both axes. A pattern in points does not by itself prove one measurement causes the other.', 'Add a point for 20 pages and 35 minutes.', 'What does one scatter point contain?', 'An x and a y measurement', 'Only a category colour'),
 L('Choose an honest baseline', 'A bar\'s length should make comparisons clear. Starting its numeric axis at zero usually avoids exaggerating small differences.', 'javascript', chart('{type:"bar",data:{labels:["Team A","Team B"],datasets:[{label:"Plants",data:[18,20]}]},options:{maintainAspectRatio:false,scales:{y:{beginAtZero:true}}}}'), 'The chart shows that 20 plants is only a little more than 18.', 'A cut-off bar baseline can make a small difference look huge. Choose scales deliberately and explain exceptions.', 'Compare the difference as two plants out of twenty.', 'Why start this bar axis at zero?', 'To make bar lengths compare amounts honestly', 'To force every bar to have the same height'),
 L('Compare two datasets', 'Two datasets can share the same categories. Each needs a clear label and a distinguishable style.', 'javascript', chart('{type:"bar",data:{labels:["Mon","Tue"],datasets:[{label:"Stories",data:[3,4],backgroundColor:"#174a8b"},{label:"Science",data:[2,3],backgroundColor:"#c76b00"}]},options:{maintainAspectRatio:false,scales:{y:{beginAtZero:true}}}}'), 'Each day has two bars so the book types can be compared.', 'Too many datasets make a chart hard to read. Keep the categories and legend understandable.', 'Read which type is higher on Tuesday.', 'Why label both datasets?', 'To explain which bars represent which measure', 'To load the chart twice'),
 L('Update data without making a new chart', 'A chart instance can receive changed data. Calling update redraws it from the new values.', 'javascript', chart('{type:"bar",data:{labels:["Mon","Tue"],datasets:[{label:"Books",data:[3,5]}]},options:{maintainAspectRatio:false}}','chart.data.datasets[0].data=[4,6];\nchart.update();'), 'The final bars show 4 and 6.', 'Changing an array alone is not the complete redraw step. Call update after the intended changes.', 'Add a label and matching data value, then update.', 'What asks Chart.js to redraw changed data?', 'chart.update()', 'canvas.textContent'),
 L('Fit a sized container', 'A responsive chart uses its parent container to decide its display size. The parent needs a clear size when the aspect ratio is not maintained.', 'javascript', chart('{type:"line",data:{labels:["A","B"],datasets:[{label:"Score",data:[2,6]}]},options:{responsive:true,maintainAspectRatio:false}}','holder.style.width="480px";'), 'The chart can resize with its dedicated holder while keeping the configured height.', 'Do not make the canvas its own sizing container. Use a relatively positioned parent.', 'Change the holder width and watch the chart resize.', 'Which element supplies the chart layout size here?', 'The parent holder', 'The dataset label'),
 L('Turn off unnecessary animation', 'Chart animation can be disabled when it is not useful. This can make repeated updates easier to follow and reduce motion.', 'javascript', chart('{type:"bar",data:{labels:["Books"],datasets:[{label:"Count",data:[5]}]},options:{animation:false,maintainAspectRatio:false}}'), 'The chart draws directly without an animated transition.', 'Respect reduced-motion preferences when choosing animation. Movement should not carry the only explanation of a change.', 'Compare a chart update with animation on and off.', 'Which option disables chart animation?', 'animation:false', 'labels:false'),
 L('Provide text outside the canvas', 'Canvas drawings do not contain normal readable HTML rows. Give the chart a name and provide its values as text or a table.', 'javascript', chart('{type:"bar",data:{labels:["Mon","Tue"],datasets:[{label:"Books",data:[3,5]}]},options:{maintainAspectRatio:false}}','canvas.setAttribute("role","img");canvas.setAttribute("aria-label","Books read: Monday 3, Tuesday 5");\nconst summary=document.createElement("p");summary.textContent="Monday: 3 books. Tuesday: 5 books.";holder.after(summary);'), 'The chart has an accessible name and a visible text summary of the exact values.', 'A title such as Chart is too vague. Include the meaningful comparison and units.', 'Write a text summary for a three-day chart.', 'Why provide text outside canvas?', 'To make the information usable without the drawing', 'To make the data secret'),
 L('Destroy an unused chart', 'A chart can keep event listeners and drawing resources. Destroy the instance when its canvas or page part is removed.', 'javascript', chart('{type:"bar",data:{labels:["Books"],datasets:[{label:"Count",data:[5]}]}}','function removeChart(){chart.destroy();holder.remove();}\n// Call removeChart when this feature leaves the page.'), 'Calling removeChart cleans up the instance and its container.', 'Destroy the old instance before reusing a canvas for another chart. Do not keep hidden unused charts running.', 'Identify the cleanup call before holder.remove.', 'Which method releases the Chart.js instance?', 'destroy', 'getState'),
])

def gsap(code):
    return 'import {gsap} from "gsap";\nconst box=document.createElement("div");box.textContent="Book";box.style.cssText="width:80px;padding:16px;background:#174a8b;color:white";document.body.append(box);\n'+code

build('gsap',
 'GSAP animates values over time. You can move a page part, fade it in or arrange several steps on a timeline. Learn clear, small movements and respect people who prefer less motion.',
 'Use a browser project with GSAP 3 installed. Each example creates its own small box. Run one example at a time with a module build tool. GSAP is not loaded by this site\'s plain runner.',
 'Uses GSAP 3 tweens, timelines, context cleanup and matchMedia.', [
 L('Move to a new position', 'A tween changes values over time. gsap.to starts from the current value and moves toward the value you give it.', 'javascript', gsap('gsap.to(box,{x:120,duration:1});'), 'The box moves 120 CSS pixels to the right over one second.', 'Duration is in seconds, not milliseconds. Keep the movement useful rather than distracting.', 'Change the distance to 60.', 'What does gsap.to describe?', 'The ending values of a tween', 'A new HTML file', slug='introduction'),
 L('Start from a chosen value', 'gsap.from starts with the supplied values and moves to the element\'s current values. It is useful for a simple entrance.', 'javascript', gsap('gsap.from(box,{opacity:0,y:20,duration:0.5});'), 'The box appears from a slightly lower, transparent starting state.', 'A from tween reads the current values as its destination. Know the element\'s normal state first.', 'Remove the y change to make only a fade.', 'Which values are supplied to gsap.from?', 'The starting values', 'Only the final values'),
 L('Set both ends explicitly', 'fromTo names both the starting and ending values. It helps when neither end should depend on the current style.', 'javascript', gsap('gsap.fromTo(box,{x:0,opacity:0.3},{x:100,opacity:1,duration:1});'), 'The box moves from x=0 to x=100 while becoming fully visible.', 'Put duration in the destination settings object. Do not hide essential content permanently if scripts fail.', 'Change the ending x to 160.', 'Why choose fromTo?', 'To state both start and end values', 'To disable all page styles'),
 L('Choose an easing curve', 'Easing changes the speed during a tween. An out ease slows near the end instead of stopping abruptly.', 'javascript', gsap('gsap.to(box,{x:160,duration:1,ease:"power2.out"});'), 'The box moves quickly at first and slows as it reaches the end.', 'A fancy bounce can make simple reading tasks harder. Choose easing that suits the purpose.', 'Compare power2.out with none.', 'What does easing change?', 'How speed changes during the tween', 'The text inside the box'),
 L('Repeat and return', 'repeat adds more plays after the first. yoyo reverses the direction on alternate plays.', 'javascript', gsap('gsap.to(box,{x:120,duration:0.6,repeat:1,yoyo:true});'), 'The box moves right once and then returns to its starting position.', 'repeat:1 means one repeat after the first play, not one play in total. Avoid endless motion without a way to stop it.', 'Predict the path if repeat is 3.', 'How many plays happen with repeat:1?', 'Two plays in total', 'One play in total'),
 L('Sequence steps on a timeline', 'A timeline groups tweens in order. By default, a new tween begins after the previous one finishes.', 'javascript', gsap('const timeline=gsap.timeline();\ntimeline.to(box,{x:120,duration:0.5}).to(box,{rotation:20,duration:0.5}).to(box,{opacity:0.5,duration:0.5});'), 'The box moves, then turns, then fades partway.', 'Rotation uses degrees in this GSAP CSS example. Do not assume it matches a 3D library\'s radians.', 'Swap the last two steps and compare the sequence.', 'When does the second tween start by default?', 'After the first finishes', 'Always at time zero'),
 L('Overlap timeline steps', 'A timeline position can make two tweens overlap. The less-than position starts a tween at the previous tween\'s start.', 'javascript', gsap('const timeline=gsap.timeline();\ntimeline.to(box,{x:120,duration:1});\ntimeline.to(box,{rotation:45,duration:1},"<");'), 'The box moves and turns at the same time.', 'Position values change timing relationships. Keep the sequence easy to reason about before adding many overlaps.', 'Replace < with > and compare the order.', 'What does the < position mean here?', 'Start at the previous tween\'s start', 'Move left by one pixel'),
 L('Stagger a group', 'Stagger starts similar tweens at slightly different times. It can guide attention across a small group.', 'javascript', 'import {gsap} from "gsap";\nconst boxes=["One","Two","Three"].map(text=>{const node=document.createElement("p");node.textContent=text;document.body.append(node);return node;});\ngsap.from(boxes,{opacity:0,y:10,duration:0.4,stagger:0.15});', 'The three paragraphs appear one after another with a short gap between starts.', 'Do not make a long list wait through a slow stagger. Readers should reach the content quickly.', 'Reduce the stagger delay to 0.05.', 'What does stagger control?', 'The gap between starting each item\'s tween', 'The words in each paragraph'),
 L('Control playback', 'A tween object has methods to play, pause and reverse. A control can let a reader choose whether motion runs.', 'javascript', gsap('const tween=gsap.to(box,{x:160,duration:2,paused:true});\nconst button=document.createElement("button");button.textContent="Play movement";button.onclick=()=>tween.play();document.body.append(button);'), 'The box waits until the Play movement button is pressed.', 'Keep playback controls as real buttons with clear labels. Do not start distracting motion before the user can act.', 'Add a second button that calls tween.pause().', 'Why set paused:true?', 'To wait for a playback action', 'To remove the box from the page'),
 L('Respect reduced motion', 'GSAP matchMedia can choose different motion based on a media query. A reduced-motion preference should get a calmer version.', 'javascript', gsap('const media=gsap.matchMedia();\nmedia.add("(prefers-reduced-motion: no-preference)",()=>{gsap.from(box,{x:-20,opacity:0,duration:0.4});});\n// With reduced motion, the normal visible box stays in place.'), 'People who allow motion get a short entrance. Those requesting less motion see the normal box directly.', 'Do not hide the box in CSS and rely on a skipped animation to reveal it.', 'Turn on reduced motion and compare the result.', 'What happens for a reduced-motion preference here?', 'The box stays visible without the entrance movement', 'The box is hidden forever'),
 L('Clean up a component animation', 'A GSAP context can collect animations created for a component. Reverting it restores their styles and removes that animation work.', 'javascript', gsap('const context=gsap.context(()=>{gsap.to(box,{x:120,duration:1});});\nfunction removeFeature(){context.revert();box.remove();}\n// Call removeFeature when this component is removed.'), 'Cleanup reverts the tween\'s changes before removing its box.', 'A removed page part should not leave running tweens behind. Keep cleanup with the feature that owns the animation.', 'Find the call that reverts the GSAP context.', 'What does context.revert help with?', 'Cleaning up a component\'s animations and styles', 'Deleting every browser cache'),
 L('Animate transforms with a purpose', 'Transform and opacity animations often avoid redoing page layout. The right choice still depends on the real page and device.', 'javascript', gsap('gsap.to(box,{scale:1.05,duration:0.2,yoyo:true,repeat:1,ease:"power1.out"});'), 'The box briefly grows and returns, using its transform rather than changing its layout width.', 'Do not assume a property is free to animate. Measure complex pages and keep the motion small.', 'Explain why this effect uses scale rather than a new width.', 'What does scale change in this example?', 'The drawn size through a transform', 'The saved text content'),
])

build('react-native',
 'React Native uses React ideas to build mobile app screens. Its View and Text components are different from web HTML. Learn a small screen, clear controls and a reading list using core mobile components.',
 'Use a current Expo project with React Native. Put examples in App.jsx. Run the project with Expo on a supported device or emulator. Native components do not run in this website\'s HTML playground.',
 'Uses stable React Native core components and react-native-safe-area-context for screen insets.', [
 L('Make a native screen', 'A View groups native page parts. Text displays words. These components are the building blocks of a React Native screen.', 'jsx', 'import {View,Text} from "react-native";\nexport default function App(){return <View style={{padding:24}}><Text>Reading club</Text></View>;}', 'The app screen shows Reading club with inner space around it.', 'Text must be inside a Text component. A browser h1 or div is not a React Native component.', 'Change the screen greeting.', 'Which component displays words?', 'Text', 'An HTML h1 tag', slug='introduction'),
 L('Create named styles', 'StyleSheet.create groups styles under names. Native style properties use JavaScript names such as backgroundColor.', 'jsx', 'import {View,Text,StyleSheet} from "react-native";\nconst styles=StyleSheet.create({page:{padding:24,backgroundColor:"#eef4ff"},title:{fontSize:24,fontWeight:"bold"}});\nexport default function App(){return <View style={styles.page}><Text style={styles.title}>Our books</Text></View>;}', 'The screen area has a pale background and a large bold title.', 'Native style values are not CSS strings with px. Use numeric values where the native style expects a number.', 'Change the title fontSize to 28.', 'How is the background property named?', 'backgroundColor', 'background-color in a JS object'),
 L('Add a button and state', 'React state remembers a value between renders. A native Button calls onPress when activated.', 'jsx', 'import {useState} from "react";\nimport {View,Text,Button} from "react-native";\nexport default function App(){const [count,setCount]=useState(0);return <View style={{padding:24}}><Text>Books: {count}</Text><Button title="Read one" onPress={()=>setCount(count+1)}/></View>;}', 'Each button press increases the visible number.', 'Use onPress for this native Button. The web onClick property is not its action prop.', 'Start the count at 2 and press the button twice.', 'Which prop handles a native button press?', 'onPress', 'onClick'),
 L('Use a text input', 'TextInput lets someone type text. onChangeText supplies the new text, so state can keep the field and screen together.', 'jsx', 'import {useState} from "react";import {View,Text,TextInput} from "react-native";\nexport default function App(){const [name,setName]=useState("");return <View style={{padding:24}}><Text>Your name</Text><TextInput accessibilityLabel="Your name" value={name} onChangeText={setName} style={{borderWidth:1,padding:12}}/><Text>Hello, {name}</Text></View>;}', 'The greeting changes as a name is typed.', 'Keep a visible label and an accessible name. A placeholder alone is not a lasting label.', 'Type a name and then clear it.', 'What value does onChangeText provide?', 'The new typed text', 'A CSS event object'),
 L('Arrange a row with flex', 'React Native uses Flexbox for layout. Its default direction is a column, so set row when items should sit beside each other.', 'jsx', 'import {View,Text} from "react-native";\nexport default function App(){return <View style={{padding:24,flexDirection:"row",gap:12}}><Text>Books read</Text><Text>4</Text></View>;}', 'The label and count appear side by side with a gap.', 'Do not assume the default direction matches browser CSS flex rows. Native defaults to column.', 'Change row to column and compare the layout.', 'What is React Native\'s default flex direction?', 'column', 'row'),
 L('Scroll a small amount of content', 'ScrollView makes its children scrollable. It is useful for a limited amount of content that can be rendered together.', 'jsx', 'import {ScrollView,Text} from "react-native";\nexport default function App(){return <ScrollView contentContainerStyle={{padding:24}}>{Array.from({length:20},(_,i)=><Text key={i} style={{padding:12}}>Reading tip {i+1}</Text>)}</ScrollView>;}', 'The tips can scroll if they do not fit on the screen.', 'ScrollView renders all its children. Use FlatList for a large or growing list.', 'Add more tips and try scrolling.', 'Which component is a better choice for a very large list?', 'FlatList', 'A ScrollView rendering every item'),
 L('Render a list efficiently', 'FlatList receives data and a function for each row. It can avoid keeping every distant row rendered at once.', 'jsx', 'import {FlatList,Text} from "react-native";\nconst books=[{id:"1",title:"Moon Trip"},{id:"2",title:"Garden Days"}];\nexport default function App(){return <FlatList data={books} keyExtractor={item=>item.id} contentContainerStyle={{padding:24}} renderItem={({item})=><Text style={{padding:12}}>{item.title}</Text>}/>;}', 'The app shows one row per book with a stable id for each.', 'Use stable unique keys. Reusing the same key for two rows can mix up item state.', 'Add a third book with a new id.', 'What does keyExtractor return?', 'A stable id for each row', 'The row text colour'),
 L('Use a local image', 'Image displays a native picture. A local file can be bundled with require so the app can include it at build time.', 'jsx', 'import {View,Image} from "react-native";\nexport default function App(){return <View style={{padding:24}}><Image source={require("./assets/garden.png")} style={{width:160,height:120}} accessibilityLabel="Our school garden"/></View>;}', 'After adding a real garden.png file, the app shows it at the chosen size.', 'The required file must exist. Use an image description when it carries information.', 'Add a real local image and choose a useful description.', 'Where does this picture come from?', 'A local bundled asset file', 'An automatically created internet photo'),
 L('Make a custom pressable control', 'Pressable can wrap a custom control. Its style callback receives pressed, so the control can show a clear response.', 'jsx', 'import {Pressable,Text,View} from "react-native";\nexport default function App(){return <View style={{padding:24}}><Pressable accessibilityRole="button" onPress={()=>console.log("Chosen")} style={({pressed})=>({padding:16,backgroundColor:pressed?"#12345a":"#174a8b"})}><Text style={{color:"white"}}>Choose a book</Text></Pressable></View>;}', 'The control darkens while pressed and logs Chosen when activated.', 'Give custom controls a role and readable label. Styling alone does not communicate their purpose.', 'Change the pressed colour while keeping text readable.', 'What does the pressed value tell the style callback?', 'Whether the control is being pressed', 'Whether the app has a user account'),
 L('Respect the safe screen area', 'Some screens have cutouts or system bars. Safe-area components add space so important content does not sit under those areas.', 'jsx', 'import {Text} from "react-native";\nimport {SafeAreaProvider,SafeAreaView} from "react-native-safe-area-context";\nexport default function App(){return <SafeAreaProvider><SafeAreaView style={{flex:1,padding:16}}><Text>Reading club</Text></SafeAreaView></SafeAreaProvider>;}', 'On a supported device, the content stays inside the safe area.', 'Install the Expo-compatible safe-area-context package. Test a real device shape rather than guessing a fixed top margin.', 'Inspect the screen near the top system bar.', 'Why use safe-area insets?', 'To avoid placing content under system cutouts and bars', 'To save every app file online'),
 L('Show an empty-list message', 'A useful list explains when it has no items. FlatList can render a dedicated empty component.', 'jsx', 'import {FlatList,Text} from "react-native";\nexport default function App(){return <FlatList data={[]} renderItem={({item})=><Text>{item.title}</Text>} ListEmptyComponent={<Text>Add your first book to begin.</Text>} contentContainerStyle={{padding:24}}/>;}', 'The empty list shows a helpful next step instead of a blank screen.', 'An empty list and a failed load are different states. Give each an accurate message in a real app.', 'Write an empty message for a garden task list.', 'What does ListEmptyComponent handle?', 'A list with no items', 'Every possible app error'),
 L('Make a local two-view demo', 'State can choose between two simple views while learning. A real navigation library adds history and platform navigation behaviour for larger apps.', 'jsx', 'import {useState} from "react";import {View,Text,Button} from "react-native";\nexport default function App(){const [detail,setDetail]=useState(false);return <View style={{padding:24}}>{detail?<><Text>Moon Trip is a space story.</Text><Button title="Back" onPress={()=>setDetail(false)}/></>:<><Text>Books</Text><Button title="Open Moon Trip" onPress={()=>setDetail(true)}/></>}</View>;}', 'The buttons switch between a list label and a book detail view within local state.', 'This small switch is not a full navigation system. It does not implement deep links or platform back history.', 'Add a second sentence to the detail view.', 'What does this demo use to choose a view?', 'A local boolean state value', 'A complete native route history automatically'),
])

def ionic(body, imports='', script=''):
    names='IonApp,IonPage,IonHeader,IonToolbar,IonTitle,IonContent'+(','+imports if imports else '')
    return f'import {{{names}}} from "@ionic/react";\n'+('import {useState} from "react";\n' if 'useState' in script else '')+f'export default function App(){{{script}return <IonApp><IonPage><IonHeader><IonToolbar><IonTitle>Reading club</IonTitle></IonToolbar></IonHeader><IonContent className="ion-padding">{body}</IonContent></IonPage></IonApp>;}}'

build('ionic',
 'Ionic provides web components styled for app screens. With React, you can build pages, lists and forms that work in a browser and can be packaged for devices. Start with the browser version and simple local state.',
 'Use an Ionic React starter with its setupIonicReact call and standard Ionic CSS imports. Put these components in App.tsx or App.jsx. The plain playground does not load Ionic styles or components.',
 'Uses Ionic React core components and controlled overlay APIs.', [
 L('Build a page shell', 'IonPage groups a screen, and IonContent gives it a scrolling content area. A toolbar can hold the screen title.', 'jsx', ionic('<p>Choose a story today.</p>'), 'The starter app displays a Reading club header and a padded content area.', 'Keep the starter Ionic setup and CSS. Component tags alone will not provide the expected app layout.', 'Change the title and first paragraph.', 'Which part holds the main scrollable content?', 'IonContent', 'IonTitle', slug='introduction'),
 L('Use a styled button', 'IonButton is a button component with Ionic styles. Its click handler can update local React state.', 'jsx', ionic('<IonButton onClick={()=>setCount(count+1)}>Read one</IonButton><p>Books: {count}</p>','IonButton','const [count,setCount]=useState(0);'), 'Each click increases the displayed count.', 'A visual button still needs a clear label. Avoid an unexplained icon as the only content.', 'Start the count at 3.', 'What changes the count here?', 'The button click handler', 'The colour of the toolbar'),
 L('Group rows in a list', 'IonList groups list rows. IonItem supplies row layout, and IonLabel holds its text.', 'jsx', ionic('<IonList><IonItem><IonLabel>Moon Trip</IonLabel></IonItem><IonItem><IonLabel>Garden Days</IonLabel></IonItem></IonList>','IonList,IonItem,IonLabel'), 'Two book rows appear inside the list.', 'Do not add click behaviour to every row unless it actually performs an action. Keep static rows simple.', 'Add a third book row.', 'Which component represents one list row?', 'IonItem', 'IonApp'),
 L('Show a card', 'An Ionic card groups a title and related content. It works well for a single book or short notice.', 'jsx', ionic('<IonCard><IonCardHeader><IonCardTitle>Book of the week</IonCardTitle></IonCardHeader><IonCardContent>A story about a moon garden.</IonCardContent></IonCard>','IonCard,IonCardHeader,IonCardTitle,IonCardContent'), 'The page shows one styled card with a heading and description.', 'A card is a visual group, not automatically a button. Use an actual control for actions.', 'Change the card to describe a hobby.', 'What belongs inside IonCardContent?', 'The card\'s main details', 'The entire app configuration'),
 L('Read a labelled input', 'IonInput can manage a typed value with React state. onIonInput provides the latest text through event.detail.value.', 'jsx', ionic('<IonInput label="Your name" labelPlacement="stacked" value={name} onIonInput={event=>setName(event.detail.value ?? "")}/><p>Hello, {name}</p>','IonInput','const [name,setName]=useState("");'), 'The greeting follows the typed name.', 'Use the Ionic event detail, not an assumed native input target. Keep a label that stays visible.', 'Type a name and then erase it.', 'Where is the typed value in this Ionic event?', 'event.detail.value', 'event.detail.colour'),
 L('Choose an option', 'IonSelect offers a controlled list of choices. onIonChange gives the selected value.', 'jsx', ionic('<IonSelect label="Book type" value={kind} onIonChange={event=>setKind(event.detail.value)}><IonSelectOption value="story">Story</IonSelectOption><IonSelectOption value="science">Science</IonSelectOption></IonSelect><p>Type: {kind}</p>','IonSelect,IonSelectOption','const [kind,setKind]=useState("story");'), 'The current book type changes after a selection.', 'Use stable option values rather than depending on their visible position.', 'Add a history option.', 'Which value identifies the science option?', 'science', 'Its row number only'),
 L('Use a checkbox', 'IonCheckbox represents a true-or-false choice. The checked value in its change event tells the current state.', 'jsx', ionic('<IonCheckbox checked={ready} onIonChange={event=>setReady(event.detail.checked)}>Ready to read</IonCheckbox><p>{ready?"Ready":"Not ready yet"}</p>','IonCheckbox','const [ready,setReady]=useState(false);'), 'Checking the box changes the message to Ready.', 'A checkbox uses checked, not a text value, for its boolean state.', 'Toggle the checkbox twice and read the messages.', 'Which event detail gives its boolean state?', 'checked', 'title'),
 L('Create responsive columns', 'Ionic\'s grid uses rows and columns. A column can use a different share of the row at a wider breakpoint.', 'jsx', ionic('<IonGrid><IonRow><IonCol size="12" sizeMd="6">Stories</IonCol><IonCol size="12" sizeMd="6">Science</IonCol></IonRow></IonGrid>','IonGrid,IonRow,IonCol'), 'The columns stack on narrow screens and share a row from the md breakpoint.', 'The sizes are parts of a 12-column system, not pixel widths.', 'Resize the browser and watch the column layout.', 'What does sizeMd="6" mean?', 'Half of a 12-part row from md upwards', 'Exactly six pixels wide'),
 L('Show a short toast message', 'A toast is a short status message that appears briefly. Its open state should stay connected to React state.', 'jsx', ionic('<IonButton onClick={()=>setOpen(true)}>Mark practice done</IonButton><IonToast isOpen={open} message="Practice marked as done" duration={2000} onDidDismiss={()=>setOpen(false)}/>','IonButton,IonToast','const [open,setOpen]=useState(false);'), 'The button opens a two-second message, then the dismiss event resets the state.', 'A disappearing toast should not be the only place for information the reader must keep. Use persistent text for important errors.', 'Change the toast to a short completion message.', 'Why handle onDidDismiss?', 'To keep React open state in step with the dismissed toast', 'To create a user account'),
 L('Open and close a modal', 'A modal is a focused layer above a page. Control its open state and give it a clear way to close.', 'jsx', ionic('<IonButton onClick={()=>setOpen(true)}>Book help</IonButton><IonModal isOpen={open} onDidDismiss={()=>setOpen(false)}><IonHeader><IonToolbar><IonTitle>Book help</IonTitle></IonToolbar></IonHeader><IonContent className="ion-padding"><p>Choose a short story first.</p><IonButton onClick={()=>setOpen(false)}>Close help</IonButton></IonContent></IonModal>','IonButton,IonModal','const [open,setOpen]=useState(false);'), 'The help button opens a modal, and the close button dismisses it.', 'Check keyboard focus and dismissal on the target device. Avoid stacking unnecessary modals.', 'Open the modal, read it and close it using the keyboard.', 'What should every simple modal make clear?', 'Its purpose and how to close it', 'Only its background colour'),
 L('Show loading as its own state', 'Loading, empty and failed are different states. A spinner can show activity while words explain what the app is waiting for.', 'jsx', ionic('<div role="status"><IonSpinner name="crescent"/><p>Loading the book list...</p></div>','IonSpinner'), 'The app shows a spinner and a readable loading message.', 'Stop showing the loading state when work succeeds or fails. A spinner forever is not useful error handling.', 'Write separate messages for an empty list and a failed load.', 'Should an empty list use a loading spinner forever?', 'No, it should explain that there are no items', 'Yes, empty and loading always mean the same thing'),
 L('Build the browser app first', 'Ionic uses web code. A browser build can be tested before optional native packaging with tools such as Capacitor.', 'text', 'Run the starter\'s build command.\nPreview its production web output.\nTest keyboard use and small-screen layout.\nCheck local state after a reload.\nAdd native packaging only when the project needs device features.', 'You get a tested web version before adding platform packaging complexity.', 'Packaging does not automatically make unsupported browser APIs work everywhere. Test each device feature separately.', 'Test one Ionic form at a narrow browser width.', 'What should be tested before optional native packaging?', 'The working web app', 'Only an app icon'),
])

build('electron',
 'Electron packages web pages as a desktop app. It has a main process for app windows and a renderer for the page. Learn a small local window and a narrow, safe bridge between the two sides.',
 'Use a local Electron project with electron installed as a dev dependency and main.cjs as its main file. Run with npx electron . after creating package.json and index.html. These APIs do not run in a web-page playground.',
 'Uses current Electron main/preload/renderer separation with context isolation and sandboxing.', [
 L('Know the two main sides', 'Electron\'s main process manages desktop windows. A renderer shows the HTML page inside a window, like a browser tab.', 'text', 'Main process: creates and manages windows.\nRenderer process: displays HTML, CSS and page JavaScript.\nPreload script: exposes a small approved bridge between them.', 'The three roles help you decide where each kind of code belongs.', 'Do not give a page full Node.js access just to avoid designing a bridge.', 'Sort window creation and button styling into the correct sides.', 'Which side creates desktop windows?', 'The main process', 'The CSS renderer alone', slug='introduction'),
 L('Create a local window', 'BrowserWindow creates a desktop window. Wait for app readiness before creating it, then load a local page.', 'javascript', '// main.cjs\nconst {app,BrowserWindow}=require("electron");\napp.whenReady().then(()=>{const win=new BrowserWindow({width:800,height:600,webPreferences:{contextIsolation:true,nodeIntegration:false,sandbox:true}});win.loadFile("index.html");});', 'A local index.html file opens in an 800 by 600 window.', 'Create the HTML file first. Keep Node integration off for renderer pages.', 'Change the window width to 900.', 'When is BrowserWindow created here?', 'After app.whenReady resolves', 'Before Electron has started'),
 L('Build the renderer page', 'The renderer can use normal HTML, CSS and browser JavaScript. It does not need Node access to show a button or change words.', 'html', '<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Reading club</title></head><body><h1>Reading club</h1><button id="hello">Say hello</button><p id="reply"></p><script src="renderer.js"></script></body></html>', 'Save as index.html and create renderer.js for the button behaviour. Electron displays it as a normal local page.', 'Keep desktop-only operations out of ordinary renderer code. Use an approved bridge when a real desktop capability is needed.', 'Add a renderer.js click handler using standard DOM methods.', 'What can the renderer use for ordinary page interaction?', 'Standard browser DOM APIs', 'Only main-process window methods'),
 L('Set a restrictive page policy', 'A Content Security Policy limits where a page can load and run content. For a local app, start with only local resources and external script files.', 'html', '<meta http-equiv="Content-Security-Policy" content="default-src \'self\'; script-src \'self\'; style-src \'self\'; img-src \'self\' data:">\n<!-- Put this in index.html head; use local external JS and CSS files. -->', 'The page accepts the allowed local resources and blocks inline scripts under this policy.', 'Do not add unsafe-eval or unsafe-inline just to hide a setup error. Move code into appropriate files.', 'Move any inline click script into renderer.js.', 'Why does this policy block inline scripts?', 'script-src allows local script files, not inline code', 'Electron cannot display any HTML'),
 L('Configure a preload file', 'A preload script runs before the page and can expose a small API. Its file path belongs in the BrowserWindow options.', 'javascript', '// Add to main.cjs when creating the window.\nconst path=require("node:path");\nconst options={webPreferences:{preload:path.join(__dirname,"preload.cjs"),contextIsolation:true,nodeIntegration:false,sandbox:true}};\n// Create the window with new BrowserWindow(options).', 'The named local preload file is loaded for that window before page scripts.', 'Use an absolute preload path. Do not let the page choose which preload file to run.', 'Find the path joined to __dirname.', 'Where is the preload path configured?', 'BrowserWindow webPreferences', 'Inside a page paragraph'),
 L('Expose one harmless value', 'contextBridge can expose a chosen value to the renderer without sharing full Node tools. Keep the exposed surface small.', 'javascript', '// preload.cjs\nconst {contextBridge}=require("electron");\ncontextBridge.exposeInMainWorld("club",{name:"Reading club"});\n// renderer.js can now read window.club.name.', 'The renderer can read the club name through window.club.', 'Do not expose require, filesystem modules or raw Electron objects to the renderer.', 'Read window.club.name from renderer.js.', 'What is exposed in this example?', 'Only a small object with the club name', 'All Node.js functions'),
 L('Ask the main process a narrow question', 'IPC lets the renderer ask the main process for an approved result. Expose one named function, not a general-purpose message sender.', 'javascript', '// preload.cjs\nconst {contextBridge,ipcRenderer}=require("electron");\ncontextBridge.exposeInMainWorld("club",{getVersion:()=>ipcRenderer.invoke("club:version")});\n// main.cjs, after creating win:\n// ipcMain.handle("club:version", event => {\n//   if(event.senderFrame !== win.webContents.mainFrame) throw new Error("Untrusted caller");\n//   return app.getVersion();\n// });', 'With the shown handler registered in main, the renderer can await window.club.getVersion().', 'Import ipcMain in main.cjs and validate the sender. Do not expose ipcRenderer itself to the page.', 'Explain why getVersion is narrower than exposing invoke.', 'What does the bridge let the page request?', 'Only the chosen version operation', 'Any arbitrary main-process operation'),
 L('Handle a bridge failure', 'A request through the bridge can reject. The renderer should show a useful message instead of leaving an unhandled error.', 'javascript', '// renderer.js, with a status element and the previous bridge installed.\nasync function showVersion(){\n  const status=document.querySelector("#status");\n  try{status.textContent=await window.club.getVersion();}\n  catch{status.textContent="The app version could not be read.";}\n}\nshowVersion();', 'A successful request shows the version. A failed request shows the fallback text.', 'Check that the target element exists in your real page. Do not display private internal error messages to the user.', 'Test the fallback by temporarily rejecting the handler.', 'Why wrap the bridge call in try and catch?', 'The promise can fail', 'It makes the version number secret'),
 L('Prevent unexpected navigation', 'A local app window should not become an unrestricted browser for unknown content. Navigation can be blocked when the app only needs its bundled page.', 'javascript', '// main.cjs, after creating win.\nwin.webContents.on("will-navigate",event=>event.preventDefault());\nwin.webContents.setWindowOpenHandler(()=>({action:"deny"}));', 'The app denies renderer-driven page navigation and new-window requests for this simple local design.', 'If external links are needed, allow only carefully checked destinations through a narrow main-process action.', 'Try a link in your local page and observe the policy.', 'Why restrict navigation in a local utility app?', 'To keep untrusted pages out of the privileged app window', 'To make the text larger'),
 L('Keep a window reference', 'The main process can keep a reference to its window and clear it when the window is closed. This helps manage the app lifecycle.', 'javascript', 'let mainWindow;\nfunction createWindow(){\n  mainWindow=new BrowserWindow({webPreferences:{contextIsolation:true,nodeIntegration:false,sandbox:true}});\n  mainWindow.loadFile("index.html");\n  mainWindow.on("closed",()=>{mainWindow=null;});\n}\n// Call createWindow after app.whenReady; import BrowserWindow in main.cjs.', 'The variable points to the open window and becomes null after that window closes.', 'Check that a window still exists before sending messages to it after asynchronous work.', 'Identify when the reference is cleared.', 'Why clear the reference on closed?', 'It no longer points to a usable open window', 'To delete index.html'),
 L('Respect desktop lifecycle rules', 'Desktop platforms have different conventions after all windows close. Electron apps commonly keep running on macOS and recreate a window when activated.', 'javascript', '// main.cjs, using createWindow from the previous lesson.\napp.on("window-all-closed",()=>{if(process.platform!=="darwin")app.quit();});\napp.on("activate",()=>{if(BrowserWindow.getAllWindows().length===0)createWindow();});', 'The app follows common close-and-reopen behaviour for the platform.', 'These handlers belong in the main process. They are not browser page events.', 'Explain when createWindow is called on activate.', 'What does the activate handler check first?', 'Whether there are any open windows', 'Whether the page has a heading'),
 L('Check the packaged app', 'A packaged desktop app can behave differently from the development folder. Test its files, permissions and error paths after packaging.', 'text', 'Use a maintained Electron packaging tool such as Electron Forge.\nBuild for a supported target platform.\nOpen the packaged app.\nCheck local images and scripts.\nTest bridge success and failure.\nConfirm no renderer Node access or unexpected new windows.', 'The check finds missing bundled files and unsafe assumptions before sharing the app.', 'Packaging is not the same as code signing or automatic updates. Configure those separately when you plan real distribution.', 'List two file paths to check in a packaged build.', 'Why test the packaged app as well as development mode?', 'Bundled paths and permissions can differ', 'Packaging automatically proves every feature works'),
])

build('ngrx',
 'NgRx helps Angular apps organise shared state. Actions say what happened, reducers choose the next values, and selectors read them. Learn each part with a small reading counter before meeting effects and SignalStore.',
 'Use an Angular project with the matching major version of @ngrx/store. Effects and SignalStore examples also need @ngrx/effects or @ngrx/signals. Save linked snippets in the files named by their imports.',
 'Uses modern NgRx Store, standalone providers and SignalStore APIs; package majors must match Angular.', [
 L('Describe an event with an action', 'An action is a named message about something that happened. NgRx action creators make those messages in a consistent shape.', 'typescript', 'import {createAction} from "@ngrx/store";\nexport const bookRead=createAction("[Reading] Book read");\nconsole.log(bookRead().type);', 'The output is [Reading] Book read.', 'An action describes an event; creating it alone does not send it to a store. Dispatch it when needed.', 'Name an action for resetting a reading counter.', 'What does an action type describe?', 'The event being reported', 'The size of an HTML heading', slug='introduction'),
 L('Put a value in an action', 'props describes values carried by an action. A reducer can read those values when it handles the event.', 'typescript', 'import {createAction,props} from "@ngrx/store";\nexport const addBooks=createAction("[Reading] Add books",props<{amount:number}>());\nconsole.log(addBooks({amount:3}).amount);', 'The action carries amount: 3.', 'Pass an object matching the declared props. Do not pass a bare number to this creator.', 'Create an action carrying amount 5.', 'How should this action creator be called?', 'addBooks({amount:3})', 'addBooks(3)'),
 L('Write a reducer rule', 'A reducer takes the old state and an action and returns the next state. It should not change the old object directly.', 'typescript', 'import {createAction,createReducer,on} from "@ngrx/store";\nconst add=createAction("[Reading] Add");\nconst reducer=createReducer({count:0},on(add,state=>({...state,count:state.count+1})));\nconsole.log(reducer({count:2},add()).count);', 'The next count is 3.', 'Plain NgRx reducers do not use Redux Toolkit\'s Immer draft rules. Return a new state object.', 'Add a reset reducer case that returns count zero.', 'What should this reducer return?', 'A new state value', 'A mutation of the old object only'),
 L('Register a root store', 'provideStore connects reducer functions to root state keys. Angular can then inject a Store service into components.', 'typescript', '// app.config.ts; counterReducer is exported from your state.ts file.\nimport {ApplicationConfig} from "@angular/core";\nimport {provideStore} from "@ngrx/store";\nimport {counterReducer} from "./state";\nexport const appConfig:ApplicationConfig={providers:[provideStore({reading:counterReducer})]};', 'The reading key is handled by counterReducer in the application store.', 'Create and export the reducer file first. The key reading becomes part of selector paths.', 'Find the root state key used for the reducer.', 'Which root key holds this reducer\'s state?', 'reading', 'providers'),
 L('Read state with a selector', 'A selector is a function that chooses a useful part of state. createSelector can remember its last input and result.', 'typescript', 'import {createSelector} from "@ngrx/store";\ninterface AppState{reading:{count:number}}\nconst selectReading=(state:AppState)=>state.reading;\nexport const selectCount=createSelector(selectReading,reading=>reading.count);\nconsole.log(selectCount({reading:{count:4}}));', 'The selector returns 4 from the reading slice.', 'Selectors should read and calculate. Do not change state or send actions inside them.', 'Create a selector that doubles the reading count.', 'What should a selector do?', 'Return a useful result from state', 'Modify the state it reads'),
 L('Use a store value as a signal', 'Store.selectSignal gives an Angular signal for a selected value. The template reads the signal by calling it.', 'typescript', '// Counter component; selectCount comes from your state file.\nimport {Component,inject} from "@angular/core";\nimport {Store} from "@ngrx/store";\nimport {selectCount} from "./state";\n@Component({selector:"app-count",template:"<p>Books: {{ count() }}</p>"})\nexport class CountComponent{count=inject(Store).selectSignal(selectCount);}', 'The paragraph follows the selected count from the registered store.', 'Use count() in the template because this value is a signal. The store and selector must already be configured.', 'Find the signal read in the template.', 'How is this selected signal read?', 'count()', 'count.value in an Angular template'),
 L('Dispatch from a component', 'A component can dispatch an action in response to a user action. The reducer remains responsible for changing shared state.', 'typescript', 'import {Component,inject} from "@angular/core";\nimport {Store} from "@ngrx/store";\nimport {bookRead} from "./state";\n@Component({selector:"app-add",template:`<button (click)="add()">Read one</button>`})\nexport class AddComponent{private store=inject(Store);add(){this.store.dispatch(bookRead());}}', 'The click sends bookRead to the store. A matching reducer can increase the count.', 'Dispatch the created action object, not the creator function itself.', 'Connect a reset button to a reset action.', 'Which call sends the action?', 'store.dispatch(bookRead())', 'bookRead without calling or dispatching it'),
 L('Group related action names', 'An action group keeps related event creators together. NgRx derives creator names from the event labels.', 'typescript', 'import {createActionGroup,emptyProps,props} from "@ngrx/store";\nconst reading=createActionGroup({source:"Reading",events:{"Add Book":props<{title:string}>(),"Clear":emptyProps()}});\nconsole.log(reading.addBook({title:"Moon Trip"}).title);', 'The generated addBook creator carries Moon Trip.', 'The event label Add Book becomes the creator name addBook. Use the generated camel-case name.', 'Create the clear action from this group.', 'Which creator comes from the event Add Book?', 'reading.addBook', 'reading["Add Book"] as the public creator'),
 L('Keep outside work in an effect', 'An effect listens for actions and can return new actions after outside work. Reducers can stay focused on state changes.', 'typescript', 'import {Injectable,inject} from "@angular/core";\nimport {Actions,createEffect,ofType} from "@ngrx/effects";\nimport {map} from "rxjs";\nimport {loadBooks,booksLoaded} from "./state";\n@Injectable()\nexport class BookEffects{private actions=inject(Actions);load=createEffect(()=>this.actions.pipe(ofType(loadBooks),map(()=>booksLoaded({titles:["Moon Trip"]}))));}\n// Register with provideEffects(BookEffects); define both action creators in state.ts.', 'A loadBooks action is followed by booksLoaded with local sample data.', 'Do not listen for the same action you return without a stopping rule. That can create an endless effect loop.', 'Name the action this effect listens for and the one it returns.', 'Why separate effects from reducers?', 'To keep outside work apart from state calculations', 'To make reducers fetch every file directly'),
 L('Keep a normalised list', 'A list with ids can be stored as an id array plus a lookup object. This makes finding one record direct and avoids duplicate copies.', 'typescript', 'const state={ids:["b1","b2"],entities:{b1:{title:"Moon Trip"},b2:{title:"Garden Days"}}};\nconsole.log(state.entities.b2.title);', 'The lookup returns Garden Days for b2. NgRx Entity can manage this common shape in larger features.', 'Keep the ids and entity records in step. A missing lookup needs a handled fallback.', 'Look up the first book by its id.', 'What does the entities object provide?', 'A record lookup by id', 'A sorted HTML table by itself'),
 L('Try a SignalStore', 'SignalStore is another NgRx way to organise state using Angular signals. Methods can call patchState to update a small part.', 'typescript', 'import {signalStore,withState,withMethods,patchState} from "@ngrx/signals";\nexport const ReadingStore=signalStore({providedIn:"root"},withState({count:0}),withMethods(store=>({add(){patchState(store,{count:store.count()+1});}})));\n// In a component, inject ReadingStore; read store.count() and call store.add().', 'The store exposes a count signal and an add method.', 'SignalStore and classic action/reducer Store are different APIs. Choose a clear approach for a feature instead of mixing names blindly.', 'Find the method that updates the count.', 'Which helper applies this SignalStore update?', 'patchState', 'document.write'),
 L('Test a state rule directly', 'A reducer can be tested without opening the page. Give it a known state and action, then compare the result.', 'typescript', 'import {createAction,createReducer,on} from "@ngrx/store";\nconst reset=createAction("[Reading] Reset");\nconst reducer=createReducer({count:0},on(reset,()=>({count:0})));\nconst before={count:5};const after=reducer(before,reset());\nconsole.assert(after.count===0);\nconsole.assert(before.count===5);', 'Both checks pass: the result resets while the original state stays unchanged.', 'Test behaviour and original-state safety. Merely checking that a reducer function exists tells little.', 'Add a test for the add action in your project.', 'Why check before.count as well?', 'To ensure the original state was not changed', 'To count how many test files exist'),
])

build('zustand',
 'Zustand keeps small shared state stores for JavaScript and React. A store can hold values and actions that change them. Learn a counter, a reading list and careful browser saving without creating an account.',
 'Use a React project with Zustand 5 installed. Hook examples belong in React components; vanilla examples use zustand/vanilla. These package imports require your own build tool.',
 'Uses Zustand 5 create, vanilla stores and persist middleware.', [
 L('Create a small store', 'A Zustand store groups values and actions. create returns a React hook that components can use to read that store.', 'javascript', 'import {create} from "zustand";\nexport const useReading=create(set=>({count:0,add:()=>set(state=>({count:state.count+1}))}));\nconsole.log(useReading.getState().count);', 'The initial count is 0.', 'Create the store outside a component for this shared client example. Creating it on every render would lose the intended shared instance.', 'Call the add action once and read the count.', 'What does create return for React use?', 'A store hook', 'A database login form', slug='introduction'),
 L('Select one value', 'A selector chooses the store value a component needs. Selecting a small value helps avoid updates from unrelated changes.', 'jsx', 'import {useReading} from "./store.js";\nexport default function Count(){const count=useReading(state=>state.count);return <p>Books: {count}</p>;}', 'The component displays the count from the store created in the first lesson.', 'Use the actual store export path. Do not select the whole store when only one value is needed.', 'Select another simple value you add to the store.', 'What does the selector return here?', 'Only the count value', 'Every browser setting'),
 L('Call an action from a button', 'An action is a function stored alongside the values. A component can select that function and call it after a click.', 'jsx', 'import {useReading} from "./store.js";\nexport default function Add(){const add=useReading(state=>state.add);return <button onClick={add}>Read one</button>;}', 'Clicking the button runs the store action and increases the count.', 'Pass the function to onClick. Writing onClick={add()} would call it while rendering.', 'Render the Count and Add components together.', 'When should add run?', 'When the button is clicked', 'Every time the component renders automatically'),
 L('Base an update on current state', 'A set callback receives the current state. It is useful when the next value depends on the previous value.', 'javascript', 'import {create} from "zustand";\nconst useScore=create(set=>({score:2,double:()=>set(state=>({score:state.score*2}))}));\nuseScore.getState().double();\nconsole.log(useScore.getState().score);', 'The score becomes 4.', 'Do not read a stale captured value when the update depends on the latest state. Use the set callback.', 'Call double twice and predict the score.', 'Which value does the set callback receive?', 'The current store state', 'Only the first state from installation'),
 L('Update one top-level field', 'By default, set merges the supplied top-level fields into state. Fields that are not supplied stay as they were.', 'javascript', 'import {create} from "zustand";\nconst useClub=create(()=>({name:"Garden",count:2}));\nuseClub.setState({count:3});\nconsole.log(useClub.getState().name);', 'The name is still Garden after count changes.', 'The merge is shallow. It does not automatically merge all levels inside a nested object.', 'Update name without changing count.', 'What happens to an untouched top-level field?', 'It stays in the state', 'It is always deleted'),
 L('Copy a nested object', 'A nested object needs its own copy when you change one of its fields. This keeps old state values unchanged.', 'javascript', 'import {create} from "zustand";\nconst useClub=create(set=>({profile:{name:"Mia",colour:"blue"},rename:name=>set(state=>({profile:{...state.profile,name}}))}));\nuseClub.getState().rename("Sam");\nconsole.log(useClub.getState().profile.colour);', 'The name changes to Sam while the colour stays blue.', 'Replacing profile with only {name} would lose its colour. Spread the old nested object when keeping its fields.', 'Change the colour while preserving the name.', 'Why spread state.profile here?', 'To keep its other fields', 'To send it to every device'),
 L('Add an item without changing the old array', 'A new array can keep the old items and add one more. This is a clear way to update list state.', 'javascript', 'import {create} from "zustand";\nconst useBooks=create(set=>({books:[],add:book=>set(state=>({books:[...state.books,book]}))}));\nuseBooks.getState().add({id:1,title:"Moon Trip"});\nconsole.log(useBooks.getState().books.length);', 'The list now has one book.', 'Do not push directly into the stored array in ordinary Zustand state. Return a new array unless using an explicit immutable-update middleware.', 'Add a second record with a unique id.', 'What does [...state.books,book] make?', 'A new array with the new book added', 'A direct mutation of the old array'),
 L('Calculate a derived count', 'A selector can calculate a value from stored data. This avoids storing two values that must always be kept in step.', 'jsx', 'import {useBooks} from "./book-store.js";\nexport default function Unread(){const count=useBooks(state=>state.books.filter(book=>!book.read).length);return <p>{count} unread books</p>;}', 'The component counts unread records from the real book-store export.', 'Keep only the source facts in state when a simple derived value is enough. Repeatedly returning a fresh object from a selector needs care.', 'Mark a record as read and check the derived count.', 'Why derive the unread count?', 'It stays based on the actual book records', 'It creates an automatic cloud backup'),
 L('Use a store without React', 'A vanilla Zustand store can be used by ordinary JavaScript. It provides getState, setState and subscribe methods.', 'javascript', 'import {createStore} from "zustand/vanilla";\nconst store=createStore(()=>({count:0}));\nstore.setState({count:4});\nconsole.log(store.getState().count);', 'The value is 4 without needing a React component.', 'A vanilla store is not a React hook. Use the matching API for the type of store you created.', 'Set the count to a different number.', 'Does a vanilla store require a React component to read it?', 'No, getState can read it', 'Yes, it can only run in JSX'),
 L('Listen and then unsubscribe', 'subscribe runs a listener after store changes. It returns a function that removes that listener.', 'javascript', 'import {createStore} from "zustand/vanilla";\nconst store=createStore(()=>({count:0}));\nconst stop=store.subscribe(state=>console.log(state.count));\nstore.setState({count:1});\nstop();\nstore.setState({count:2});', 'The listener prints 1. It does not print 2 after stop is called.', 'Remove listeners that belong to a removed page part. Otherwise they can keep doing work.', 'Find the cleanup call in the example.', 'What does stop() do here?', 'Removes this subscription', 'Deletes all store values'),
 L('Save a browser preference', 'The persist middleware can store selected state in browser storage. It restores that state on a later visit in the same browser.', 'javascript', 'import {create} from "zustand";\nimport {persist} from "zustand/middleware";\nexport const useTheme=create(persist(set=>({theme:"light",choose:theme=>set({theme})}),{name:"club-theme",partialize:state=>({theme:state.theme})}));', 'The theme choice can survive a reload where localStorage is available.', 'Browser storage may be cleared or blocked. Never store passwords or promise that this syncs across devices.', 'Choose a theme and reload the local page.', 'Does this middleware create cross-device sync?', 'No, this example uses local browser storage', 'Yes, it creates accounts automatically'),
 L('Reset only the intended data', 'A reset action should set the values that belong to its feature. Keep its scope clear so it does not erase unrelated browser choices.', 'javascript', 'import {create} from "zustand";\nconst useReading=create(set=>({count:0,title:"",reset:()=>set({count:0,title:""})}));\nuseReading.setState({count:5,title:"Moon Trip"});\nuseReading.getState().reset();\nconsole.log(useReading.getState().count);', 'The reading values return to their starting values and the reset action remains available.', 'Do not clear all localStorage to reset one feature. Remove only the keys that feature owns if storage is used.', 'List the values this reset changes.', 'What should a feature reset affect?', 'Only its intended data', 'Every website\'s stored data'),
])

build('jquery',
 'jQuery is a JavaScript library used by many existing websites. It gives short tools for selecting page parts and handling events. Learn what those tools do, then see how similar jobs work with the browser DOM.',
 'Use a local HTML page that loads jQuery 3.7 before these scripts. Examples need that library; the plain playground does not include it. Put the script after the example markup.',
 'Uses stable jQuery 3.7 APIs for maintaining existing sites.', [
 L('Select a page part', 'The jQuery function, often written $, selects page elements using a CSS selector. Its result is a jQuery collection.', 'html', '<h1 id="title">Reading club</h1><script>console.log($("#title").text());</script>', 'With jQuery loaded first, the console shows Reading club.', 'Load the library before using $. A jQuery collection is not the same thing as a plain DOM element.', 'Select a paragraph using its id.', 'What does $("#title") return?', 'A jQuery collection of matching elements', 'The text of every file', slug='introduction'),
 L('Set plain text', 'The text method reads or replaces text. A replacement is treated as words rather than HTML markup.', 'html', '<p id="note">Waiting</p><script>$("#note").text("Bring a notebook.");</script>', 'The paragraph shows Bring a notebook.', 'Use text for ordinary user content. html interprets markup and needs trusted content.', 'Change the reminder words.', 'Which method writes plain text?', 'text', 'html for all untrusted input'),
 L('Add and remove classes', 'A class name lets CSS handle the appearance. jQuery can add or remove that name without rewriting the stylesheet.', 'html', '<style>.bright{background:gold;}</style><p id="note">A useful tip</p><script>$("#note").addClass("bright");</script>', 'The note becomes gold through its bright class.', 'Pass the class name without a dot. A dot belongs in a selector, not the addClass value.', 'Remove bright after adding it.', 'What value belongs in addClass?', 'bright', '.bright'),
 L('Respond to a click', 'The on method adds an event handler. It can run a function whenever the chosen element receives that event.', 'html', '<button id="hello">Say hello</button><p id="reply"></p><script>$("#hello").on("click",()=>$("#reply").text("Hello!"));</script>', 'The button fills the reply paragraph after a click.', 'Pass a function to on. Calling the function while attaching the handler would run it too soon.', 'Change the button reply.', 'When does this handler run?', 'On a click event', 'Only while installing jQuery'),
 L('Read a typed value', 'The val method reads the current value of a form control. This is different from reading the text inside an ordinary paragraph.', 'html', '<label for="name">Name</label><input id="name" value="Mia"><button id="read">Read name</button><script>$("#read").on("click",()=>console.log($("#name").val()));</script>', 'Clicking the button logs whatever name is currently in the input.', 'Use val for inputs. text does not read the typed value.', 'Type another name before clicking.', 'Which method reads input text?', 'val', 'text'),
 L('Read a checkbox state', 'The prop method reads a live element property. A checkbox\'s checked property tells whether it is checked now.', 'html', '<label><input id="ready" type="checkbox">Ready</label><button id="check">Check</button><script>$("#check").on("click",()=>console.log($("#ready").prop("checked")));</script>', 'The console shows true or false for the current check state.', 'The checked HTML attribute describes an initial state. Use the property for the current state.', 'Check and uncheck the box before reading it.', 'What reports the checkbox\'s live state?', 'prop("checked")', 'Only its original HTML attribute'),
 L('Find a nearby parent', 'closest walks up from an element until it finds a matching ancestor or the element itself. It is useful for finding the card that contains a button.', 'html', '<article class="card"><button id="choose">Choose</button></article><script>$("#choose").closest(".card").addClass("selected");</script>', 'The article receives the selected class. Add a CSS rule to make that state visible.', 'closest starts at the selected element and moves upward. It does not search all descendants.', 'Add a visible border for the selected class.', 'Which direction does closest search?', 'The element and then its ancestors', 'Only deeper child elements'),
 L('Append a safe new item', 'You can create an element and set its text before adding it to a list. This avoids building HTML from untrusted text.', 'html', '<ul id="books"></ul><script>const item=$("<li>").text("Moon Trip");$("#books").append(item);</script>', 'The list gains one book item.', 'Do not join raw user text into an HTML string. Use text on the created element.', 'Append another title using a new li.', 'Why use .text on the new item?', 'To treat the title as plain text', 'To run the title as JavaScript'),
 L('Handle future child buttons', 'A delegated handler is attached to a parent and checks matching child elements. It can work for children added later.', 'html', '<div id="books"><button data-title="Moon Trip">Choose</button></div><script>$("#books").on("click","button",function(){console.log($(this).attr("data-title"));});</script>', 'Clicking the child button logs its data-title value through the parent handler.', 'This example uses a normal function so this refers to the matched button. Arrow functions do not bind their own this.', 'Add a second child button after the handler is attached.', 'Where is the delegated listener attached?', 'On the books parent', 'On every future element automatically as a separate listener'),
 L('Remove only your handler', 'Event namespaces let you label handlers for later cleanup. off can remove just the handlers with that label.', 'javascript', 'const button=$("#hello");\nbutton.on("click.club",()=>console.log("Hello"));\n// When this feature is removed:\nbutton.off("click.club");', 'The final line removes this feature\'s click handler while leaving differently named handlers alone.', 'Calling off("click") removes all click handlers attached through jQuery on that selection. Be precise.', 'Choose a namespace for a book-picker feature.', 'Why add .club to the event name?', 'To remove this group of handlers precisely', 'To change the browser event into a CSS class'),
 L('Load a local JSON file', 'getJSON makes a request for JSON data. done handles success, while fail handles a failed request.', 'javascript', '$.getJSON("/books.json")\n .done(data=>console.log(data))\n .fail(()=>console.log("The book list could not load."));', 'With a real local books.json file, its data is logged. A failed request shows a clear message.', 'Do not assume a request always succeeds. The file must be served from an allowed address.', 'Create a small local JSON list and test the failure path too.', 'Which callback handles a failed request?', 'fail', 'done only'),
 L('Compare with the standard DOM', 'Many small jQuery jobs also have built-in browser equivalents. Understanding both helps maintain old code and write new code without unnecessary libraries.', 'javascript', '// jQuery:\n$("#title").text("Reading club");\n// Standard DOM, on a page with this element:\ndocument.querySelector("#title").textContent="Reading club";', 'Both lines set the heading text. Only the first needs jQuery.', 'The native query can return null. Add a check when an element may be absent.', 'Rewrite a simple jQuery class change with classList.', 'Which line works without loading jQuery?', 'The document.querySelector line', 'The dollar-sign line'),
])

build('redux',
 'Redux keeps shared app state in one store. Actions describe changes, and reducers decide the next state. This course uses Redux Toolkit to make those rules short and clear, with tiny counters and reading lists.',
 'Use a JavaScript project with @reduxjs/toolkit installed. React examples also need react-redux and React. These imports require your project build tool and are not available in the plain playground.',
 'Uses Redux Toolkit 2 and React Redux hooks.', [
 L('Meet a store and an action', 'A store keeps state. An action is a small message saying what happened, such as one more book being read.', 'javascript', 'import {configureStore,createSlice} from "@reduxjs/toolkit";\nconst slice=createSlice({name:"reading",initialState:{count:0},reducers:{add(state){state.count++;}}});\nconst store=configureStore({reducer:slice.reducer});\nstore.dispatch(slice.actions.add());\nconsole.log(store.getState().count);', 'The console shows 1 after the action is dispatched.', 'Read state through the store. Do not change store.getState() values directly.', 'Dispatch add a second time and predict the count.', 'What does dispatch send to the store?', 'An action message', 'A CSS file', slug='introduction'),
 L('Name a slice of state', 'A slice groups one part of state with the reducers that change it. Its name also forms the start of generated action types.', 'javascript', 'import {createSlice} from "@reduxjs/toolkit";\nconst reading=createSlice({name:"reading",initialState:0,reducers:{add:state=>state+1}});\nconsole.log(reading.actions.add().type);', 'The action type is reading/add.', 'Choose a meaningful unique slice name so action messages are easy to understand.', 'Change the slice name and inspect the action type.', 'What forms the generated action type here?', 'The slice name and reducer name', 'The current browser width'),
 L('Carry a value in an action', 'An action payload carries the information needed for a change. A reducer can use that value to choose the next state.', 'javascript', 'import {configureStore,createSlice} from "@reduxjs/toolkit";\nconst slice=createSlice({name:"reading",initialState:0,reducers:{add:(state,action)=>state+action.payload}});\nconst store=configureStore({reducer:slice.reducer});\nstore.dispatch(slice.actions.add(3));\nconsole.log(store.getState());', 'The store becomes 3 because the action payload is 3.', 'Keep payloads clear and serialisable. Do not put a DOM element or a function in ordinary app state.', 'Dispatch add with 5 and predict the state.', 'What is action.payload in this call?', '3', 'The word reading'),
 L('Return a new primitive value', 'When a slice state is a number or string, its reducer returns the next value. A primitive cannot be changed like a draft object field.', 'javascript', 'import {createSlice} from "@reduxjs/toolkit";\nconst slice=createSlice({name:"score",initialState:0,reducers:{reset:()=>0,add:state=>state+1}});\nconsole.log(slice.reducer(7,slice.actions.reset()));', 'The reset reducer returns 0 from a previous state of 7.', 'Writing state++ without returning a primitive value does not correctly replace this number state.', 'Run the add reducer with a starting value of 7.', 'How does a number-state reducer replace its value?', 'By returning the new number', 'By changing a hidden field on the number'),
 L('Update draft object fields', 'Redux Toolkit uses Immer inside createSlice reducers. It records changes to a draft and makes a safe next state.', 'javascript', 'import {createSlice} from "@reduxjs/toolkit";\nconst slice=createSlice({name:"book",initialState:{title:"Moon Trip",read:false},reducers:{markRead(state){state.read=true;}}});\nconst before={title:"Moon Trip",read:false};\nconst after=slice.reducer(before,slice.actions.markRead());\nconsole.log(before.read,after.read);', 'The output is false true. The original object remains unchanged.', 'Draft-style updates work inside Toolkit reducers. They do not make direct mutation of arbitrary store state safe.', 'Compare the before and after objects.', 'Does this reducer change the original before object?', 'No, Toolkit produces a next state', 'Yes, all old state is overwritten'),
 L('Add a list item', 'A list reducer can add a record with a stable id. The payload supplies the record to add.', 'javascript', 'import {createSlice} from "@reduxjs/toolkit";\nconst slice=createSlice({name:"books",initialState:[],reducers:{add(state,action){state.push(action.payload);}}});\nconst next=slice.reducer([],slice.actions.add({id:1,title:"Moon Trip"}));\nconsole.log(next[0].title);', 'The new list contains a book titled Moon Trip.', 'Create unique ids before dispatching or with a prepare callback. Do not use a random value inside a pure reducer.', 'Add a second book with a different id.', 'What should each book have for stable identification?', 'A unique id', 'The same list position forever'),
 L('Select a useful piece of state', 'A selector is a function that reads state and returns the part a caller needs. It keeps state lookup rules in one place.', 'javascript', 'const selectUnread=state=>state.books.filter(book=>!book.read);\nconst state={books:[{id:1,read:true},{id:2,read:false}]};\nconsole.log(selectUnread(state).length);', 'The selector finds one unread book.', 'A selector should read and calculate. It should not dispatch actions or change the state it receives.', 'Add another unread record and predict the count.', 'What should a selector do?', 'Read state and return a useful result', 'Mutate the original state'),
 L('Combine related slices', 'A store can hold several slices under different keys. Each slice still handles its own part of the state.', 'javascript', 'import {configureStore,createSlice} from "@reduxjs/toolkit";\nconst books=createSlice({name:"books",initialState:[],reducers:{}});\nconst theme=createSlice({name:"theme",initialState:"light",reducers:{}});\nconst store=configureStore({reducer:{books:books.reducer,theme:theme.reducer}});\nconsole.log(store.getState().theme);', 'The root state has books and theme keys. The theme value is light.', 'Selectors need to follow the actual root shape. Moving a slice under a key changes its lookup path.', 'Write a selector for the books list in this root state.', 'Where is the theme stored?', 'state.theme', 'state.books.theme'),
 L('Provide the store to React', 'React Redux Provider makes one store available to components under it. Hooks can then read from that store.', 'jsx', '// main.jsx; create and export store from your own store.js first.\nimport {createRoot} from "react-dom/client";\nimport {Provider} from "react-redux";\nimport {store} from "./store.js";\nimport App from "./App.jsx";\ncreateRoot(document.getElementById("root")).render(<Provider store={store}><App/></Provider>);', 'Components inside App can use React Redux hooks with the supplied store.', 'Create the store once for this client app. Do not recreate it on every component render.', 'Find which part of the tree receives the store.', 'What does Provider make available?', 'The Redux store to descendant components', 'A database password to every visitor'),
 L('Read and dispatch from React', 'useSelector reads a store value for a component. useDispatch gives the component a way to send actions.', 'jsx', 'import {useSelector,useDispatch} from "react-redux";\nexport default function Counter(){const count=useSelector(state=>state.reading.count);const dispatch=useDispatch();return <button onClick={()=>dispatch({type:"reading/add"})}>Books: {count}</button>;}\n// Use a Provider store with a reading slice and an add reducer.', 'The button reads the count and asks the store to add one. Its display follows the updated value.', 'The selector path and action type must match your configured slice.', 'Find the selector path in the component.', 'Which hook sends actions?', 'useDispatch', 'useSelector'),
 L('Handle an async task state', 'An async thunk creates pending, fulfilled and rejected actions for a promise. A reducer can use these to show task progress.', 'javascript', 'import {createAsyncThunk,configureStore,createSlice} from "@reduxjs/toolkit";\nconst load=createAsyncThunk("books/load",async()=>["Moon Trip"]);\nconst slice=createSlice({name:"books",initialState:[],reducers:{},extraReducers:builder=>{builder.addCase(load.fulfilled,(_state,action)=>action.payload);}});\nconst store=configureStore({reducer:slice.reducer});\nstore.dispatch(load()).then(()=>console.log(store.getState()[0]));', 'The fulfilled action stores the returned list and the console shows Moon Trip.', 'Real requests can fail. Add rejected and pending handling when the UI needs progress and error messages.', 'Name the three lifecycle actions of an async thunk.', 'Which action carries a successful returned value?', 'fulfilled', 'pending'),
 L('Keep state changes predictable', 'Reducers should be predictable: the same state and action should produce the same result. Create outside facts before sending the action.', 'javascript', 'const action={type:"books/added",payload:{id:"book-1",title:"Moon Trip"}};\nfunction reducer(state=[],action){if(action.type==="books/added")return [...state,action.payload];return state;}\nconsole.log(reducer([],action).length);', 'The same empty state and action always give a one-item list.', 'Do not fetch data, read the clock or generate random ids inside a reducer. Those are outside jobs.', 'Call the reducer twice with the same inputs and compare.', 'Why keep reducers predictable?', 'It makes changes easier to test and understand', 'It makes all network requests instant'),
])

build('rxjs',
 'RxJS works with values that arrive over time. An observable is a stream of those values. Operators can change, filter or combine streams. Learn with small number streams before using clicks and waiting tasks.',
 'Use a JavaScript or TypeScript project with RxJS 7 installed. Run imports through the project tool. Browser event examples need the stated HTML element. This site does not include RxJS in its runner.',
 'Uses RxJS 7 observable, pipe and operator APIs.', [
 L('Listen to a small stream', 'An observable sends values to a subscriber. of makes a stream from the values you give it.', 'javascript', 'import {of} from "rxjs";\nof(2,4,6).subscribe(value=>console.log(value));', 'The console prints 2, then 4, then 6. This stream then completes.', 'Subscribing is how you start listening. Not every observable starts work before someone subscribes.', 'Add one more number to the of call.', 'What does subscribe do?', 'Listens for stream values', 'Turns numbers into CSS', slug='introduction'),
 L('Transform each value', 'map changes each emitted value into a new value. pipe connects an operator to the stream.', 'javascript', 'import {of,map} from "rxjs";\nof(1,2,3).pipe(map(value=>value*10)).subscribe(console.log);', 'The outputs are 10, 20 and 30.', 'map transforms each value; it does not remove values based on a true-or-false rule.', 'Change the multiplier to 5.', 'Which operator transforms each value?', 'map', 'filter'),
 L('Keep values that pass a rule', 'filter allows values through only when its test is true. Other values are left out.', 'javascript', 'import {of,filter} from "rxjs";\nof(2,7,4,9).pipe(filter(value=>value>5)).subscribe(console.log);', 'Only 7 and 9 are printed.', 'The filter function should return a true-or-false result. It does not change the values that pass.', 'Change the rule to values below 5.', 'What happens to a value whose filter test is false?', 'It is left out', 'It becomes zero'),
 L('Take only a few values', 'take limits how many values a subscriber receives. It completes after that number has arrived.', 'javascript', 'import {of,take} from "rxjs";\nof("A","B","C").pipe(take(2)).subscribe(console.log);', 'The outputs are A and B, then the subscription completes.', 'take counts emissions, not seconds. A slow stream may take time to emit two values.', 'Use take(1) and predict the output.', 'What does take(2) count?', 'Two emitted values', 'Two seconds'),
 L('Watch a timed stream', 'interval emits a growing count at a chosen time gap. Its first value is zero, after the first gap.', 'javascript', 'import {interval,take} from "rxjs";\ninterval(1000).pipe(take(3)).subscribe(console.log);', 'About one second apart, the outputs are 0, 1 and 2, then it stops.', 'Timing is approximate and can be delayed by the environment. Do not use it as an exact clock.', 'Change the gap to 500 milliseconds.', 'What is interval\'s first emitted number?', '0', '1'),
 L('Turn clicks into a stream', 'fromEvent listens to events from a target. Each matching event becomes a stream value.', 'javascript', '// Page needs a button with id choose.\nimport {fromEvent,take} from "rxjs";\nconst button=document.querySelector("#choose");\nif(button)fromEvent(button,"click").pipe(take(2)).subscribe(()=>console.log("Chosen"));', 'The first two clicks log Chosen. The stream then stops listening.', 'Check that the target exists. A missing element cannot be an event target.', 'Click three times and count the messages.', 'How many clicks does this subscription handle?', 'Two', 'Every click forever'),
 L('Stop listening when finished', 'A subscription has an unsubscribe method. Calling it stops that subscription and runs the source cleanup.', 'javascript', 'import {interval} from "rxjs";\nconst subscription=interval(1000).subscribe(console.log);\nsetTimeout(()=>subscription.unsubscribe(),2500);', 'Normally 0 and 1 appear before the subscription is stopped around 2.5 seconds.', 'Clean up long-lived subscriptions when their page part is removed. Do not rely on every source completing itself.', 'Find the line that stops the subscription.', 'What does unsubscribe stop?', 'This subscription\'s listening and associated work', 'Every JavaScript program on the computer'),
 L('Send values with a Subject', 'A Subject is both something you can subscribe to and something you can send values into. It shares new values with current subscribers.', 'javascript', 'import {Subject} from "rxjs";\nconst choices=new Subject();\nchoices.subscribe(value=>console.log("A",value));\nchoices.subscribe(value=>console.log("B",value));\nchoices.next("Moon Trip");', 'Both current subscribers receive Moon Trip.', 'A plain Subject does not replay an old value to someone who subscribes later.', 'Add a later subscriber after next and observe it.', 'Who gets a plain Subject\'s new value?', 'Its current subscribers', 'All future subscribers automatically forever'),
 L('Keep the latest value', 'A BehaviorSubject starts with one value and gives the latest value to each new subscriber.', 'javascript', 'import {BehaviorSubject} from "rxjs";\nconst score=new BehaviorSubject(0);\nscore.next(5);\nscore.subscribe(console.log);', 'The new subscriber immediately receives 5.', 'Choose a meaningful initial value. A BehaviorSubject always needs one.', 'Subscribe before next as well and compare the messages.', 'What does this late subscriber receive first?', '5, the latest value', 'Nothing until another next call'),
 L('Combine the latest values', 'combineLatest waits until each input has a value, then emits their latest values together when either changes.', 'javascript', 'import {BehaviorSubject,combineLatest} from "rxjs";\nconst books=new BehaviorSubject(2);\nconst pages=new BehaviorSubject(10);\ncombineLatest([books,pages]).subscribe(([b,p])=>console.log(b*p));\nbooks.next(3);', 'The output is 20, then 30 after books changes.', 'A source with no first value can make the combined stream wait. Know which inputs have emitted.', 'Change pages to 12 and predict the next total.', 'When can combineLatest first emit?', 'After every input has emitted at least once', 'Before any input has a value'),
 L('Keep only the latest waiting job', 'switchMap switches to a new inner stream and unsubscribes from the previous one. It is useful when only the newest request matters.', 'javascript', 'import {Subject,timer,switchMap,map} from "rxjs";\nconst search=new Subject();\nsearch.pipe(switchMap(word=>timer(100).pipe(map(()=>word)))).subscribe(console.log);\nsearch.next("moon");\nsearch.next("garden");', 'After the wait, only garden is printed. The earlier timer was cancelled by the newer input.', 'Use switchMap only when cancelling the old work is suitable. Do not use it for writes that must all finish.', 'Explain why moon is not printed.', 'What happens to the previous inner stream?', 'It is unsubscribed when a new one is chosen', 'It always finishes and replaces the newest result'),
 L('Handle a stream error', 'catchError can replace a failed stream with another observable. A fallback can give the caller a useful value instead of an unhandled failure.', 'javascript', 'import {throwError,catchError,of} from "rxjs";\nthrowError(()=>new Error("No books"))\n .pipe(catchError(()=>of([])))\n .subscribe(books=>console.log(books.length));', 'The fallback emits an empty list, so the console shows 0.', 'Return an observable from catchError. Also decide whether the UI should explain the error instead of silently hiding it.', 'Replace the empty list with a visible fallback message stream.', 'What must catchError return here?', 'A replacement observable', 'Only a CSS colour'),
])

build('nuxt',
 'Nuxt adds page routing and project tools to Vue. This starter course builds a small site from pages and shared layouts. It uses local content and a static build, so the finished sample does not need a login or a database.',
 'Use a Nuxt 3 project for these file paths. Examples go in the files named in comments. Remove the starter welcome screen and use NuxtPage in app.vue. Nuxt code needs its own build tool.',
 'Targets Nuxt 3 directory conventions, Vue 3 and static generation.', [
 L('Show the current page', 'NuxtPage is the place where Nuxt displays the page chosen by the address. It belongs in the app wrapper.', 'vue', '<!-- app.vue -->\n<template><NuxtPage /></template>\n\n<!-- pages/index.vue, separate file -->\n<template><main><h1>Reading club</h1><p>Pick a book today.</p></main></template>', 'The home route shows the index page through NuxtPage.', 'The welcome starter component does not automatically display your pages. Use NuxtPage.', 'Change the index page greeting.', 'What does NuxtPage display?', 'The page matching the current route', 'Every page at the same time', slug='introduction'),
 L('Add a file route', 'A Vue file in pages becomes a route. index.vue is the home page, while books.vue makes /books.', 'vue', '<!-- pages/books.vue -->\n<template><main><h1>Books</h1><ul><li>Moon Trip</li></ul></main></template>', 'The /books route shows the book list.', 'These paths use Nuxt 3 conventions. Follow the matching version when copying a project layout.', 'Add pages/about.vue with a short club description.', 'Which file makes the /books route?', 'pages/books.vue', 'components/books.css'),
 L('Navigate with NuxtLink', 'NuxtLink provides a normal link meaning while letting Nuxt handle local route navigation.', 'vue', '<!-- pages/index.vue -->\n<template><main><h1>Reading club</h1><NuxtLink to="/books">Read the book list</NuxtLink></main></template>', 'The link opens the existing /books route.', 'The route must exist. A link does not create a page just by naming it.', 'Add a link back to / from the books page.', 'Which prop gives NuxtLink its destination?', 'to', 'colour'),
 L('Share a layout', 'A layout wraps pages with shared content. Its slot is the space for the selected page.', 'vue', '<!-- app.vue -->\n<template><NuxtLayout><NuxtPage /></NuxtLayout></template>\n\n<!-- layouts/default.vue, separate file -->\n<template><div><header>Reading club</header><slot/><footer>Keep reading</footer></div></template>', 'Pages appear between the shared header and footer.', 'Leave a slot in the layout. Without it, the page content has nowhere to appear.', 'Add a navigation link to the default layout.', 'What does the layout slot hold?', 'The selected page content', 'A server password'),
 L('Reuse a component', 'Nuxt can auto-import components from its components folder. A component can receive props just like other Vue components.', 'vue', '<!-- components/BookCard.vue -->\n<script setup>defineProps({title:String});</script><template><h2>{{ title }}</h2></template>\n\n<!-- pages/books.vue, separate file -->\n<template><main><h1>Books</h1><BookCard title="Moon Trip"/></main></template>', 'The books page shows the auto-imported BookCard with its title.', 'Use the expected components folder and component name. A file in an unrelated folder is not automatically discovered.', 'Render two BookCard components with different titles.', 'Where does this auto-imported component live?', 'components/BookCard.vue', 'public/BookCard.txt'),
 L('Set the page title', 'useSeoMeta describes title and description values for a page. Nuxt can include them in the generated document head.', 'vue', '<!-- pages/books.vue -->\n<script setup>useSeoMeta({title:"Books | Reading Club",description:"Our club\'s short reading list."});</script>\n<template><main><h1>Books</h1></main></template>', 'The browser tab and generated page metadata use the supplied title and description.', 'Keep the title and description about the actual page. Metadata does not replace visible content.', 'Write metadata for the about page.', 'What does useSeoMeta configure?', 'Page metadata such as the title', 'The number of rows in a database'),
 L('Share state with a key', 'useState creates state that Nuxt can share safely within one app visit. A key identifies which state value is being requested.', 'vue', '<!-- pages/index.vue -->\n<script setup>const count=useState("books-read",()=>0);</script>\n<template><button @click="count++">Books read: {{ count }}</button></template>', 'The button updates the shared value named books-read.', 'Do not use a module-level changing ref as shared per-user server state. useState is designed for Nuxt rendering.', 'Read the same books-read key in another component.', 'What is the purpose of the useState key?', 'To identify the shared state value', 'To create a login password'),
 L('Load a local JSON file', 'useFetch can load data and give the page loading and error state. A file in public can act as simple build-time content.', 'vue', '<!-- Put {"title":"Moon Trip"} in public/book.json. -->\n<!-- pages/books.vue -->\n<script setup>const {data,error}=await useFetch("/book.json");</script>\n<template><p v-if="error">The book could not load.</p><h1 v-else>{{ data?.title }}</h1></template>', 'With the real JSON file present, the page shows Moon Trip. A failure has its own message.', 'Create the file and use its root URL, /book.json. Do not treat public files as secret.', 'Change the local JSON title and rebuild.', 'Where should this public JSON file be stored?', 'public/book.json', 'In a password field'),
 L('Read a route value', 'A bracketed page file captures part of an address. useRoute gives the page access to that route value.', 'vue', '<!-- pages/books/[slug].vue -->\n<script setup>const route=useRoute();</script>\n<template><main><h1>Book: {{ route.params.slug }}</h1></main></template>', 'The route /books/moon-trip displays Book: moon-trip. Static generation must be told which such routes to build.', 'A dynamic route pattern does not generate every possible static page by itself.', 'Open the moon-trip route and inspect the shown slug.', 'What is slug in /books/moon-trip?', 'moon-trip', 'books'),
 L('Run browser-only work after mount', 'Some APIs exist only in the browser. onMounted runs after the component is mounted there, so it can safely read browser-only objects.', 'vue', '<!-- pages/index.vue -->\n<script setup>const width=ref(null);onMounted(()=>{width.value=window.innerWidth;});</script>\n<template><p>Window width: {{ width ?? "Checking" }}</p></template>', 'The page begins with Checking and then shows the browser width after mounting.', 'Do not read window at the top of code that may also run during generation or server rendering.', 'Find the browser-only line in the mounted callback.', 'Why read window inside onMounted?', 'window is available in the browser, not every rendering context', 'It makes the window secret'),
 L('Keep a public setting public', 'Runtime config separates public settings from server-only settings. Anything placed in public is visible to browser code.', 'typescript', '// nuxt.config.ts\nexport default defineNuxtConfig({runtimeConfig:{public:{clubName:"Reading club"}}});\n\n// In a component script setup:\n// const config = useRuntimeConfig();\n// Read config.public.clubName in the template.', 'A component can read the public club name. It is ordinary visible configuration, not a secret.', 'Never put an admin key or password in public runtime config.', 'Choose one harmless setting suitable for public config.', 'Can public runtime config safely hide a secret?', 'No, browser users can read it', 'Yes, its name keeps it hidden'),
 L('Generate static pages', 'Nuxt can build a site as static files. List dynamic routes that cannot be found by following ordinary page links.', 'typescript', '// nuxt.config.ts\nexport default defineNuxtConfig({nitro:{prerender:{routes:["/books/moon-trip","/books/garden-days"]}}});\n// Run: npx nuxi generate\n// Serve the generated .output/public directory on a static host.', 'The output contains generated pages and assets for the listed routes and the pages found by the generator.', 'A static host cannot run Nuxt server endpoints. Keep this sample\'s content available at build time.', 'Check that both listed book routes have output files.', 'Which folder is served for this static result?', '.output/public', 'The source pages folder directly'),
])

build('remix',
 'Remix ideas now live in React Router\'s framework tools. This course teaches routes, nested pages and browser data loading in a small single-page app. It uses local data and avoids a runtime server.',
 'Use React Router 7 framework mode, the continuation of Remix\'s framework approach. Save files at the shown app paths. Set ssr:false in react-router.config.ts for this browser-only course. React tooling is required.',
 'Uses React Router 7 framework mode and clientLoader/clientAction concepts, not legacy Remix package imports.', [
 L('Choose browser rendering', 'A single-page app loads a browser shell and lets routes choose its content. React Router framework mode can build this with server rendering turned off.', 'typescript', '// react-router.config.ts\nimport type {Config} from "@react-router/dev/config";\nexport default {ssr:false} satisfies Config;', 'The framework builds an app intended to run its route work in the browser.', 'This setting does not turn server-only loaders into browser code. Use clientLoader for browser loading.', 'Find the ssr setting in the framework config.', 'Which value turns off server rendering here?', 'ssr:false', 'ssr:"always"', slug='introduction'),
 L('Declare route files', 'A route config maps addresses to route modules. An index route is the default page for its parent address.', 'typescript', '// app/routes.ts\nimport {type RouteConfig,index,route} from "@react-router/dev/routes";\nexport default [index("routes/home.tsx"),route("books","routes/books.tsx")] satisfies RouteConfig;', 'The home module handles /, and the books module handles /books once those files are created.', 'Route file paths are relative to the app directory. Create the named files.', 'Add an about route entry and its module.', 'Which helper names a default route?', 'index', 'font'),
 L('Write a route page', 'A route module exports a component to show for its address. Start with a small page before adding any data work.', 'tsx', '// app/routes/home.tsx\nexport default function Home(){return <main><h1>Reading club</h1><p>Choose a book today.</p></main>;}', 'The home route shows a heading and paragraph.', 'The route module needs a default component export. A file of plain text is not a route component.', 'Change the home page paragraph.', 'What does the default export provide?', 'The route\'s page component', 'A database connection'),
 L('Use links for navigation', 'Link changes the route while keeping the useful meaning of a link. Its to prop gives the destination.', 'tsx', '// app/routes/home.tsx\nimport {Link} from "react-router";\nexport default function Home(){return <main><h1>Reading club</h1><Link to="/books">Open the book list</Link></main>;}', 'The link opens the configured books route.', 'A Link is for navigation. Use a button for an action that does not go to a new address.', 'Add a link back to the home route from books.', 'Which prop gives the link destination?', 'to', 'method'),
 L('Show a nested route', 'A parent route can wrap child routes. Outlet is the place where the matched child appears.', 'tsx', '// app/routes/books-layout.tsx\nimport {Outlet} from "react-router";\nexport default function BooksLayout(){return <section><h1>Our books</h1><Outlet/></section>;}\n// Configure this module as a parent with child routes in app/routes.ts.', 'When this route has a matching child, the child is shown below Our books.', 'Without Outlet, nested child content has no place to render.', 'Mark the exact place a child page will appear.', 'What does Outlet display?', 'The matching child route', 'All routes in the project'),
 L('Read an address parameter', 'A route parameter captures a value from an address. useParams reads the captured values as strings.', 'tsx', '// Configure route("books/:slug", "routes/book.tsx") first.\n// app/routes/book.tsx\nimport {useParams} from "react-router";\nexport default function Book(){const {slug}=useParams();return <h1>Book: {slug}</h1>;}', 'At /books/moon-trip, the page shows Book: moon-trip.', 'A route parameter is input from the address. Check it before using it for a sensitive or limited lookup.', 'Try a second slug and see the new heading.', 'What is captured by :slug?', 'The matching address segment', 'The entire CSS file'),
 L('Load data in the browser', 'clientLoader prepares route data in the browser. It can read a local public JSON file and return the values a page needs.', 'tsx', '// app/routes/books.tsx; also create public/books.json as a JSON array.\nimport {useLoaderData} from "react-router";\nexport async function clientLoader(){const response=await fetch("/books.json");if(!response.ok)throw new Error("Books could not load");return response.json();}\nexport default function Books(){const books=useLoaderData<typeof clientLoader>();return <ul>{books.map((book:{id:number;title:string})=><li key={book.id}>{book.title}</li>)}</ul>;}', 'The route reads the real JSON file and shows one item per book.', 'Check failed responses. A public JSON file is readable by every visitor and should contain no secrets.', 'Create two book records with unique ids.', 'Where does clientLoader run?', 'In the browser', 'Only inside a private database server'),
 L('Show a first-load fallback', 'A HydrateFallback can show a simple message while route data needed during initial hydration is loading.', 'tsx', '// Add these exports to a route module that has clientLoader.\nexport function HydrateFallback(){return <p>Loading the book list...</p>;}\n// To require client loading during hydration for this route:\n// clientLoader.hydrate = true as const;', 'The fallback gives the reader a clear waiting message while that route prepares its initial client data.', 'The fallback is part of a route with a clientLoader. It is not a substitute for a component that renders the finished data.', 'Write a short loading message that names the task.', 'Why show a fallback during loading?', 'To explain that the route is preparing its data', 'To hide every possible error forever'),
 L('Give the active link a clear style', 'NavLink knows whether its destination is the active route. You can use that state to show which page is selected.', 'tsx', 'import {NavLink} from "react-router";\nexport default function Menu(){return <nav aria-label="Main"><NavLink to="/books" className={({isActive})=>isActive?"current":""}>Books</NavLink></nav>;}', 'On the books route, the link receives the current class and active-page semantics.', 'Use more than colour when useful, such as an underline. Ensure the current class has a real CSS rule.', 'Add a visible underline rule for .current.', 'What does isActive describe?', 'Whether the link destination matches the active route', 'Whether the visitor has an account'),
 L('Use search values in the address', 'Search parameters let a page keep small filter choices in the URL. A copied address can then describe the same filter.', 'tsx', 'import {useSearchParams} from "react-router";\nexport default function Filter(){const [params,setParams]=useSearchParams();return <label>Topic <input value={params.get("topic")||""} onChange={e=>setParams({topic:e.target.value})}/></label>;}', 'Typing changes the topic search value in the address as well as the input.', 'Do not put private data in a URL. Addresses can be copied, logged and kept in history.', 'Type space and read the topic parameter.', 'Where is this filter choice stored?', 'In the URL search parameters', 'Only inside a hidden server session'),
 L('Explain a route error', 'A route ErrorBoundary can show a useful message when loading or rendering fails. It keeps the failure from becoming a blank screen.', 'tsx', '// Export from the route module.\nimport {useRouteError,isRouteErrorResponse,Link} from "react-router";\nexport function ErrorBoundary(){const error=useRouteError();return <main><h1>We could not open this page</h1><p>{isRouteErrorResponse(error)?`Status ${error.status}`:"Please try again."}</p><Link to="/">Go home</Link></main>;}', 'A caught route error displays a clear message and a home link.', 'Do not show private internal error details to visitors. Keep technical logs separate from the visible message.', 'Test the view with a deliberately missing local data file.', 'What should an error view give the reader?', 'A clear explanation and a way to continue', 'Only a blank page'),
 L('Serve the browser build', 'A browser route app needs its static host to return the app shell for supported client-side addresses. Otherwise a direct visit can fail before React runs.', 'text', 'Run the project build command.\nServe the generated build/client files.\nConfigure the static host fallback to index.html for client routes.\nOpen /books directly in a new tab.\nCheck that real asset requests still return their actual files.', 'Both link navigation and direct route visits can open the app when the host fallback is correct.', 'Do not return HTML for a missing JavaScript file. Keep asset handling separate from route fallback behaviour.', 'Test /books by typing its address directly.', 'Why does a client route need a host fallback?', 'The host must provide the app shell before the router can run', 'The browser cannot follow ordinary links'),
])

build('astro',
 'Astro makes content pages with very little browser JavaScript by default. It can add interactive parts only where needed. Learn pages, layouts and small content lists before adding an optional interactive island.',
 'Use an Astro project. Save examples at the shown src paths. Astro files are built into HTML and need the Astro tool; they do not run as plain HTML in this playground.',
 'Uses Astro component syntax, static output and client directives for interactive islands.', [
 L('Make an Astro page', 'An .astro page combines a frontmatter script with HTML-like markup. Frontmatter runs while Astro builds or renders the page.', 'astro', '---\nconst club = "Reading club";\n---\n<h1>{club}</h1>\n<p>Pick a story today.</p>\n<!-- Save as src/pages/index.astro. -->', 'The home page contains the club heading and paragraph as HTML.', 'Frontmatter does not automatically run in the browser. Do not put a click handler there and expect it to attach itself.', 'Change the club value and rebuild the page.', 'When does this frontmatter run in a static site?', 'During the build', 'On every mouse movement', slug='introduction'),
 L('Make a second page', 'Astro uses the pages folder to create routes. A file named books.astro creates a books page.', 'astro', '<!-- src/pages/books.astro -->\n<h1>Our books</h1><ul><li>Moon Trip</li></ul>', 'The /books route contains a simple book list.', 'Create pages in src/pages. A component in src/components does not get its own route automatically.', 'Add an about.astro page.', 'Which folder creates routes?', 'src/pages', 'src/components only'),
 L('Use normal page links', 'Astro pages can use ordinary HTML links. A normal link works without adding a client router.', 'astro', '<!-- src/pages/index.astro -->\n<nav aria-label="Main"><a href="/books">Book list</a><a href="/about">About the club</a></nav>', 'The links open the corresponding pages when those pages exist.', 'Link destinations must exist in the built site. Use clear words to describe each destination.', 'Add a home link on the books page.', 'Does a normal Astro page link require a React router?', 'No, a normal HTML link works', 'Yes, all links require React'),
 L('Reuse a component with props', 'An Astro component can read values from Astro.props. A parent passes those values as attributes on the component.', 'astro', '---\n// src/components/BookCard.astro\nconst {title} = Astro.props;\n---\n<article><h2>{title}</h2></article>', 'Import BookCard into a page and use <BookCard title="Moon Trip" /> to show the title.', 'This is a component file, not a route. Import it in the page frontmatter before using its tag.', 'Render two BookCard components with different titles.', 'Where does an Astro component read its props?', 'Astro.props', 'window.passwords'),
 L('Wrap content with a layout', 'A layout component can provide the outer page structure. A slot marks where a page puts its own content.', 'astro', '---\n// src/layouts/Base.astro\nconst {title="Reading club"}=Astro.props;\n---\n<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>{title}</title></head><body><slot/></body></html>', 'A page that imports Base and wraps its content in <Base> gets the shared document structure.', 'Leave a slot for the page content. A layout without one hides its children.', 'Use Base around the books page.', 'What does slot show in this layout?', 'Content supplied by the page', 'Every file in the public folder'),
 L('Make a list at build time', 'A static data array can become HTML during the Astro build. The browser receives the finished list without needing to run the map call.', 'astro', '---\nconst books=["Moon Trip","Garden Days"];\n---\n<ul>{books.map(title=><li>{title}</li>)}</ul>', 'The output HTML has one list item for each title.', 'Changing the source array needs a rebuild for a static site. This is not live database data.', 'Add a third title and rebuild.', 'Does the browser need to run this map to see the list?', 'No, the build produces the list HTML', 'Yes, every static list needs a browser framework'),
 L('Keep component CSS nearby', 'Styles in an Astro component are scoped by default. They can style that component without using a global rule for the whole site.', 'astro', '<article><h2>Moon Trip</h2><p>A short story.</p></article>\n<style>article{border:1px solid navy;padding:1rem;}h2{color:navy;}</style>', 'The article has a navy border and its heading is navy.', 'Use an explicit global style only when it should affect the wider page. Do not make every rule global by accident.', 'Change the card padding.', 'What is the default reach of these component styles?', 'The component\'s matching markup', 'Every unrelated page on the internet'),
 L('Add a browser script', 'A script tag can run client-side JavaScript on an Astro page. Use it only for the page behaviour you actually need.', 'astro', '<button id="greet">Say hello</button><p id="reply"></p>\n<script>document.querySelector("#greet")?.addEventListener("click",()=>{const reply=document.querySelector("#reply");if(reply)reply.textContent="Hello, reader!";});</script>', 'The button updates the paragraph in the browser.', 'If a component repeats on a page, repeated ids can cause trouble. Use a custom element or scoped selection for repeated controls.', 'Change the reply message.', 'Which code runs in the browser here?', 'The script tag code', 'Every frontmatter line automatically'),
 L('Use a real public asset', 'The public folder holds files copied without processing. Their URLs start at the site root.', 'astro', '<!-- Save a real file at public/club.svg. -->\n<img src="/club.svg" width="120" height="120" alt="Reading club badge">', 'The browser loads the local badge and can reserve its dimensions.', 'The file must exist. Do not include public in its browser URL.', 'Add a real local badge file with useful alt text.', 'What URL serves public/club.svg?', '/club.svg', '/public/club.svg'),
 L('Build known dynamic routes', 'A bracketed page can use a route value. For static output, getStaticPaths lists the pages Astro should create.', 'astro', '---\n// src/pages/books/[slug].astro\nexport function getStaticPaths(){return [{params:{slug:"moon-trip"},props:{title:"Moon Trip"}},{params:{slug:"garden-days"},props:{title:"Garden Days"}}];}\nconst {title}=Astro.props;\n---\n<h1>{title}</h1>', 'The build creates two book pages with their own titles.', 'Every parameter value must match the bracketed route name. Unknown slugs are not generated automatically.', 'Add one more known book path.', 'What does getStaticPaths list?', 'The dynamic pages to generate', 'All installed browser extensions'),
 L('Add one interactive island', 'An island is a component that receives browser JavaScript only when a client directive asks for it. The rest of the page can stay plain HTML.', 'astro', '---\n// After adding the official React integration and a real Counter.jsx component:\nimport Counter from "../components/Counter.jsx";\n---\n<h1>Reading club</h1><Counter client:load />', 'The React counter becomes interactive when its JavaScript loads. The heading stays ordinary static HTML.', 'Install the matching Astro integration and create Counter first. Importing a component without a client directive does not make it interactive.', 'Explain which part of the page needs client JavaScript.', 'What does client:load ask Astro to do?', 'Hydrate this component in the browser', 'Turn the whole site into a database'),
 L('Build and inspect the output', 'A static build produces HTML and assets that a static host can serve. Inspecting the output helps you see how little client code a content page needs.', 'bash', 'npm run build\nnpm run preview', 'Astro builds the site to dist and starts a local preview using the project\'s preview command.', 'Preview is a local check, not a deployment by itself. Test generated route links and missing assets before publishing.', 'Inspect a generated page and check its image requests.', 'What does a static Astro build produce?', 'HTML and assets for a static host', 'A requirement for a login database'),
])

build('svelte',
 'Svelte builds interactive pages from small component files. Its compiler prepares those files for the browser. Learn values, buttons and lists with Svelte 5 runes, one small example at a time.',
 'Use a Svelte 5 project. Save a single example as App.svelte unless file names say otherwise. The Svelte compiler is required; these snippets do not run as plain HTML or JavaScript.',
 'Uses Svelte 5 runes, event properties and snippet children.', [
 L('Show a value', 'A Svelte component can contain a script and page markup. Curly brackets show a JavaScript value in the markup.', 'svelte', '<script>const club="Reading club";</script>\n<h1>{club}</h1>', 'The component shows Reading club as its heading.', 'A .svelte file needs the Svelte build tool. A browser cannot use the source file directly.', 'Change the club name in the script.', 'What does {club} insert?', 'The value named club', 'The whole script as visible text', slug='introduction'),
 L('Use state that changes', 'The $state rune creates a value Svelte tracks. Changing it can update the part of the page that reads it.', 'svelte', '<script>let count=$state(0);</script>\n<button onclick={()=>count++}>Books: {count}</button>', 'Each click adds one to the visible book count.', 'In runes mode, use $state for values whose changes should update the page.', 'Start count at 4 and click twice.', 'Which rune makes count reactive?', '$state', '$html'),
 L('Derive a new value', 'The $derived rune describes a value calculated from other state. It stays connected to the values it uses.', 'svelte', '<script>let books=$state(2);let pages=$derived(books*10);</script>\n<button onclick={()=>books++}>Add book</button><p>{pages} pages</p>', 'The page starts at 20 pages and increases by ten with each click.', 'Keep a derived expression focused on calculating a value, not changing another value.', 'Change ten pages per book to twelve.', 'What makes pages update?', 'The books value it depends on changes', 'Only a page reload'),
 L('Show one of two messages', 'An if block includes content only when its condition is true. Its else part handles the other case.', 'svelte', '<script>let ready=$state(false);</script>\n<button onclick={()=>ready=!ready}>Change</button>\n{#if ready}<p>Ready to read</p>{:else}<p>Choose a book</p>{/if}', 'The button switches between the two messages.', 'Close the block with {/if}. Curly-brace blocks are Svelte syntax, not ordinary HTML tags.', 'Write two messages for a different task.', 'Which message appears when ready is false?', 'Choose a book', 'Ready to read'),
 L('Make a keyed list', 'An each block repeats markup for a list. A key identifies each item even when its position changes.', 'svelte', '<script>const books=[{id:1,title:"Moon Trip"},{id:2,title:"Garden Days"}];</script>\n<ul>{#each books as book (book.id)}<li>{book.title}</li>{/each}</ul>', 'The two titles appear as list items with stable book ids.', 'Use a unique stable id. A repeated key cannot identify two different items.', 'Add a third book with id 3.', 'What does (book.id) provide?', 'A key for the repeated item', 'A page colour'),
 L('Bind typed text', 'bind:value links an input to a state value. Typing changes that state and the parts of the page that read it.', 'svelte', '<script>let name=$state("");</script>\n<label>Name <input bind:value={name}></label><p>Hello, {name}</p>', 'The greeting changes as the person types.', 'Keep a label. Binding a value does not give an input an accessible name.', 'Type a name and clear the input.', 'What does bind:value connect?', 'The input value and name state', 'The input and a remote database'),
 L('Read a prop', 'A prop is a value given to a component by its parent. $props reads those inputs in Svelte 5.', 'svelte', '<!-- BookCard.svelte -->\n<script>let {title="Untitled"}=$props();</script><h2>{title}</h2>\n\n<!-- App.svelte, separate file -->\n<script>import BookCard from "./BookCard.svelte";</script><BookCard title="Moon Trip" />', 'The BookCard child shows Moon Trip. The default title is used if the parent omits it.', 'Save the parts as separate files. Do not overwrite a parent\'s input as a substitute for sending an event or callback.', 'Omit the title to see the default.', 'Which rune reads component props?', '$props', '$query'),
 L('Call a parent callback', 'A callback prop lets a child ask its parent to react. The parent decides what to do with the supplied value.', 'svelte', '<!-- Choose.svelte -->\n<script>let {onchoose}=$props();</script><button onclick={()=>onchoose("Moon Trip")}>Choose</button>\n\n<!-- App.svelte, separate file -->\n<script>import Choose from "./Choose.svelte";let title=$state("");</script><Choose onchoose={value=>title=value}/><p>{title}</p>', 'The child button calls the parent callback, and the parent displays the title.', 'This component expects an onchoose function. Supply it, or define a fallback if the callback is optional.', 'Pass a callback that adds a short prefix to the title.', 'Who decides what happens after the callback?', 'The parent that supplies the function', 'The CSS file'),
 L('Share a snippet of content', 'A snippet is a reusable piece of Svelte markup. A children snippet lets a wrapper render content supplied by its parent.', 'svelte', '<!-- Note.svelte -->\n<script>let {children}=$props();</script><aside><h2>Note</h2>{@render children?.()}</aside>\n\n<!-- App.svelte, separate file -->\n<script>import Note from "./Note.svelte";</script><Note><p>Bring a notebook.</p></Note>', 'The supplied paragraph appears inside the note wrapper.', 'Use {@render} for a snippet. A snippet is not plain text to insert with braces.', 'Change the supplied paragraph to another reminder.', 'What does {@render children?.()} do?', 'Renders the supplied children snippet if it exists', 'Downloads all child files'),
 L('Run and clean up an effect', 'An effect runs after Svelte updates the page and tracks reactive values it reads. Its returned function cleans up work before rerun or removal.', 'svelte', '<script>\nlet count=$state(0);\n$effect(()=>{const timer=setInterval(()=>count++,1000);return ()=>clearInterval(timer);});\n</script><p>{count} seconds</p>', 'The timer increments the state. Cleanup stops that timer when the component is removed.', 'Use effects for outside work such as timers. Use $derived for a value that can be calculated from state.', 'Identify the cleanup function in the effect.', 'Which tool is better for a calculated total?', '$derived', 'An effect that repeatedly writes the total'),
 L('Style one component', 'Svelte scopes ordinary component styles so they mainly affect markup from that component. This helps avoid accidental changes elsewhere.', 'svelte', '<h2>Garden club</h2><p>Plant a seed today.</p>\n<style>h2{color:navy;}p{line-height:1.6;}</style>', 'The component heading is navy and its paragraph has roomy line spacing.', 'Global styles need a deliberate global rule. Do not assume a child component\'s private markup will match a parent rule.', 'Add a border to this component\'s paragraph.', 'Why scope component CSS?', 'To reduce unintended changes to other components', 'To stop all CSS from being created'),
 L('Add items with a form', 'A form can add trimmed text to a reactive list. Handling submit supports both the button and the Enter key.', 'svelte', '<script>let title=$state("");let books=$state([]);let next=1;function add(event){event.preventDefault();if(title.trim()){books.push({id:next++,title:title.trim()});title="";}}</script>\n<form onsubmit={add}><label>Book <input bind:value={title}></label><button>Add</button></form><ul>{#each books as book (book.id)}<li>{book.title}</li>{/each}</ul>', 'Each non-empty submitted title becomes a list item. The form clears after adding it.', 'This list is kept only while the page is open. Add storage separately if saving is a real requirement.', 'Try submitting an empty title and then a real title.', 'Why check title.trim()?', 'To avoid adding an empty or space-only title', 'To remove the page heading'),
])

build('nextjs',
 'Next.js adds page routing and build tools to React. This course uses a small site that can be exported as static files. Learn page files, shared layouts and browser interactions without adding a login or database.',
 'Use a Next.js App Router project. Save files at the paths shown. For these static examples, use output: "export" in next.config.ts and npm run build. They need Next.js tools and do not run in this playground.',
 'Uses the modern App Router and static export; dynamic server features are outside this starter course.', [
 L('Make the home page', 'A page.tsx file defines what a route shows. In the app folder, page.tsx is the home page.', 'tsx', '// app/page.tsx\nexport default function Home(){return <main><h1>Reading club</h1><p>Pick a story today.</p></main>;}', 'The home address shows the Reading club heading and paragraph.', 'A file must export its page component as default. Folder and file names decide the route.', 'Change the home-page greeting.', 'Which file defines the App Router home page?', 'app/page.tsx', 'app/home.css', slug='introduction'),
 L('Add a second route', 'A folder with its own page.tsx makes a route. The folder name becomes part of the web address.', 'tsx', '// app/books/page.tsx\nexport default function Books(){return <main><h1>Books</h1><ul><li>Moon Trip</li></ul></main>;}', 'The /books address displays this page.', 'A folder alone is not a visible page. Add a page.tsx file with a component.', 'Create an /about page with a short club description.', 'What address matches app/books/page.tsx?', '/books', '/page.tsx'),
 L('Move between pages with Link', 'Next.js Link makes navigation between local routes. It preserves normal link meaning while allowing the framework to handle the move.', 'tsx', '// app/page.tsx\nimport Link from "next/link";\nexport default function Home(){return <main><h1>Reading club</h1><Link href="/books">Read the book list</Link></main>;}', 'The link moves to the existing /books route.', 'The destination still needs to exist. Use clear link text instead of only Click here.', 'Add a Link from the book page back to the home page.', 'What does Link need in href?', 'The route address to open', 'The component\'s variable name'),
 L('Share a root layout', 'A layout wraps pages that belong under it. The root layout includes the html and body elements for the app.', 'tsx', '// app/layout.tsx\nimport type { ReactNode } from "react";\nexport default function RootLayout({children}:{children:ReactNode}){return <html lang="en"><body><header>Reading club</header>{children}<footer>Keep reading</footer></body></html>;}', 'The header and footer surround each page placed inside this root layout.', 'Render children or the selected page will not appear. The root layout needs html and body.', 'Add a short navigation area to the layout.', 'What does children represent in this layout?', 'The page or nested layout inside it', 'Every file on the computer'),
 L('Add page metadata', 'Metadata gives a page a browser title and search description. Static values can be exported from a server page file.', 'tsx', '// app/books/page.tsx\nexport const metadata={title:"Books | Reading Club",description:"A short list of books for our club."};\nexport default function Books(){return <main><h1>Books</h1><p>Moon Trip</p></main>;}', 'The browser tab uses Books | Reading Club. The page includes the description metadata.', 'Do not export metadata from a file marked use client. Put metadata in a server page or layout.', 'Write a clear title for an about page.', 'What does metadata.title change?', 'The browser page title', 'Every heading automatically'),
 L('Create a browser counter', 'A Client Component can use browser state and click handlers. The use client line marks that boundary.', 'tsx', '// app/Counter.tsx\n"use client";\nimport {useState} from "react";\nexport default function Counter(){const [count,setCount]=useState(0);return <button onClick={()=>setCount(count+1)}>Books: {count}</button>;}', 'When imported and rendered by a page, the counter updates after clicks in the browser.', 'The marker is a quoted string before imports. A Client Component is not a safe place for secret keys.', 'Render Counter from app/page.tsx and click it.', 'Why does this component use use client?', 'It needs browser interaction and React state', 'It must keep a server password'),
 L('Pass data to a client part', 'A server page can pass simple serialisable values into a Client Component. The client can then use the values for interaction.', 'tsx', '// app/Greeting.tsx\n"use client";\nexport default function Greeting({name}:{name:string}){return <button onClick={()=>alert("Hi, "+name)}>Greet {name}</button>;}\n\n// app/page.tsx, separate file\nimport Greeting from "./Greeting";\nexport default function Home(){return <Greeting name="Mia"/>;}', 'The button shows Mia and uses that string when clicked.', 'Do not pass an ordinary server function as a client prop. Data crossing the boundary needs an allowed serialisable form.', 'Pass a different name from the page.', 'Which prop crosses the boundary here?', 'The string name', 'A private server connection'),
 L('Use a local public file', 'Files in public are served from the site root. Their folder name is not included in the public URL.', 'tsx', '// Put a real club.svg file in public/club.svg.\n// app/page.tsx\nexport default function Home(){return <main><h1>Our club</h1><img src="/club.svg" width="120" height="120" alt="Garden club badge"/></main>;}', 'The page loads the actual local club.svg file and reserves its image space.', 'Create the file before using the path. /public/club.svg is not the correct public URL.', 'Add a real badge file and check its request.', 'What URL serves public/club.svg?', '/club.svg', '/public/club.svg'),
 L('Keep component styles local', 'A CSS module gives a component named classes that are scoped by the build. It helps avoid collisions with another component\'s class names.', 'tsx', '// app/Card.module.css\n// .card { padding: 1rem; border: 1px solid navy; }\n\n// app/page.tsx\nimport styles from "./Card.module.css";\nexport default function Home(){return <article className={styles.card}><h1>Book of the week</h1></article>;}', 'After saving the actual CSS rule in Card.module.css, the card gets a border and padding.', 'The CSS comment here labels a separate file. Put real CSS, without the comment markers, in that file.', 'Change the card border colour in the module.', 'How does JSX use the module class?', 'styles.card', 'The literal string styles.card'),
 L('Generate a small set of book pages', 'A dynamic route folder uses a value from the address. Static export needs to know its allowed values at build time.', 'tsx', '// app/books/[slug]/page.tsx\nexport function generateStaticParams(){return [{slug:"moon-trip"},{slug:"garden-days"}];}\nexport default async function Book({params}:{params:Promise<{slug:string}>}){const {slug}=await params;return <main><h1>{slug}</h1></main>;}', 'The build can create pages for moon-trip and garden-days. Their titles show the matching slug.', 'Static export cannot invent a new unknown route at request time. List the pages you want to build.', 'Add one more slug to generateStaticParams.', 'Why provide generateStaticParams for these exported pages?', 'To name the routes that must be built', 'To make every possible address exist'),
 L('Show a helpful missing-page message', 'A not-found file supplies a useful message when the app reaches a missing page. Give the reader a way back.', 'tsx', '// app/not-found.tsx\nimport Link from "next/link";\nexport default function NotFound(){return <main><h1>Page not found</h1><p>Try the book list.</p><Link href="/books">Open books</Link></main>;}', 'The app has a clear missing-page view with a working local route link.', 'On a static host, also configure the host to serve the exported 404 page for unknown addresses.', 'Write a short missing-page message in plain language.', 'What should a useful missing-page view include?', 'A clear message and a way to continue', 'Only an unexplained error number'),
 L('Export static site files', 'A static export builds files that a static host can serve. Browser interactions can still work without a runtime application server.', 'typescript', '// next.config.ts\nimport type {NextConfig} from "next";\nconst config:NextConfig={output:"export"};\nexport default config;\n// Run npm run build. The exported site is written to out/.', 'The out folder contains deployable static files for the supported routes.', 'Static export does not support features that need a live Next.js server. Use local build-time content for this course.', 'Find the exported HTML for the home and books routes.', 'Which folder contains the static export?', 'out', 'node_modules only'),
])
